/*
 * xxHash - fast non-cryptographic hash
 * Reimplementation of the XXH32 / XXH64 algorithms.
 *
 * BSD 2-Clause License
 */
#ifndef XXH_H
#define XXH_H

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef enum { XXH_OK = 0, XXH_ERROR } XXH_errorcode;

/* ---- one-shot ---- */
uint32_t XXH32(const void *input, size_t len, uint32_t seed);
uint64_t XXH64(const void *input, size_t len, uint64_t seed);

/* ---- streaming, 32-bit ---- */
typedef struct {
    uint32_t total_len_32;
    uint32_t large_len;
    uint32_t v[4];
    uint32_t mem32[4];
    uint32_t memsize;
} XXH32_state_t;

void          XXH32_reset(XXH32_state_t *st, uint32_t seed);
XXH_errorcode XXH32_update(XXH32_state_t *st, const void *input, size_t len);
uint32_t      XXH32_digest(const XXH32_state_t *st);

/* ---- streaming, 64-bit ---- */
typedef struct {
    uint64_t total_len;
    uint64_t v[4];
    uint64_t mem64[4];
    uint32_t memsize;
} XXH64_state_t;

void          XXH64_reset(XXH64_state_t *st, uint64_t seed);
XXH_errorcode XXH64_update(XXH64_state_t *st, const void *input, size_t len);
uint64_t      XXH64_digest(const XXH64_state_t *st);

#ifdef __cplusplus
}
#endif

#endif /* XXH_H */

