/*
 * xxHash - fast non-cryptographic hash (XXH32 / XXH64)
 * Original algorithm by Yann Collet; this is an independent implementation
 * written from the published algorithm description.
 *
 * BSD 2-Clause License
 */
#include "xxh.h"
#include <string.h>

/* ------------------------------------------------------------------ */
/* portable little-endian access                                       */
/* ------------------------------------------------------------------ */

static uint32_t xh_read32(const void *p)
{
    const unsigned char *b = (const unsigned char *)p;
    return (uint32_t)b[0] | ((uint32_t)b[1] << 8) |
           ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
}

static uint64_t xh_read64(const void *p)
{
    const unsigned char *b = (const unsigned char *)p;
    return (uint64_t)xh_read32(b) | ((uint64_t)xh_read32(b + 4) << 32);
}

static uint32_t xh_rotl32(uint32_t x, int r)
{
    return (x << r) | (x >> (32 - r));
}

static uint64_t xh_rotl64(uint64_t x, int r)
{
    return (x << r) | (x >> (64 - r));
}

/* ------------------------------------------------------------------ */
/* XXH32                                                               */
/* ------------------------------------------------------------------ */

#define P32_1 2654435761U
#define P32_2 2246822519U
#define P32_3 3266489917U
#define P32_4  668265263U
#define P32_5  374761393U

static uint32_t xh32_round(uint32_t acc, uint32_t lane)
{
    acc += lane * P32_2;
    acc  = xh_rotl32(acc, 13);
    acc *= P32_1;
    return acc;
}

static uint32_t xh32_avalanche(uint32_t h)
{
    h ^= h >> 15;
    h *= P32_2;
    h ^= h >> 13;
    h *= P32_3;
    h ^= h >> 16;
    return h;
}

/* consume the trailing (< 16) bytes and finalize */
static uint32_t xh32_finalize(uint32_t h, const unsigned char *p, size_t len)
{
    while (len >= 4) {
        h += xh_read32(p) * P32_3;
        h  = xh_rotl32(h, 17) * P32_4;
        p += 4;
        len -= 4;
    }
    while (len > 0) {
        h += (uint32_t)(*p++) * P32_5;
        h  = xh_rotl32(h, 11) * P32_1;
        len--;
    }
    return xh32_avalanche(h);
}

uint32_t XXH32(const void *input, size_t len, uint32_t seed)
{
    const unsigned char *p = (const unsigned char *)input;
    uint32_t h;

    if (len >= 16) {
        const unsigned char *const limit = p + len - 16;
        uint32_t v1 = seed + P32_1 + P32_2;
        uint32_t v2 = seed + P32_2;
        uint32_t v3 = seed;
        uint32_t v4 = seed - P32_1;
        do {
            v1 = xh32_round(v1, xh_read32(p));      p += 4;
            v2 = xh32_round(v2, xh_read32(p));      p += 4;
            v3 = xh32_round(v3, xh_read32(p));      p += 4;
            v4 = xh32_round(v4, xh_read32(p));      p += 4;
        } while (p <= limit);
        h = xh_rotl32(v1, 1) + xh_rotl32(v2, 7) +
            xh_rotl32(v3, 12) + xh_rotl32(v4, 18);
    } else {
        h = seed + P32_5;
    }
    h += (uint32_t)len;
    return xh32_finalize(h, p, len & 15);
}

void XXH32_reset(XXH32_state_t *st, uint32_t seed)
{
    memset(st, 0, sizeof(*st));
    st->v[0] = seed + P32_1 + P32_2;
    st->v[1] = seed + P32_2;
    st->v[2] = seed;
    st->v[3] = seed - P32_1;
}

XXH_errorcode XXH32_update(XXH32_state_t *st, const void *input, size_t len)
{
    const unsigned char *p = (const unsigned char *)input;
    const unsigned char *const end = p + len;

    if (input == NULL)
        return len ? XXH_ERROR : XXH_OK;

    st->total_len_32 += (uint32_t)len;
    st->large_len |= (uint32_t)((len >= 16) | (st->total_len_32 >= 16));

    if (st->memsize + len < 16) {
        memcpy((unsigned char *)st->mem32 + st->memsize, p, len);
        st->memsize += (uint32_t)len;
        return XXH_OK;
    }

    if (st->memsize) {
        size_t const fill = 16 - st->memsize;
        memcpy((unsigned char *)st->mem32 + st->memsize, p, fill);
        st->v[0] = xh32_round(st->v[0], xh_read32(&st->mem32[0]));
        st->v[1] = xh32_round(st->v[1], xh_read32(&st->mem32[1]));
        st->v[2] = xh32_round(st->v[2], xh_read32(&st->mem32[2]));
        st->v[3] = xh32_round(st->v[3], xh_read32(&st->mem32[3]));
        p += fill;
        st->memsize = 0;
    }

    if (p <= end - 16) {
        const unsigned char *const limit = end - 16;
        do {
            st->v[0] = xh32_round(st->v[0], xh_read32(p)); p += 4;
            st->v[1] = xh32_round(st->v[1], xh_read32(p)); p += 4;
            st->v[2] = xh32_round(st->v[2], xh_read32(p)); p += 4;
            st->v[3] = xh32_round(st->v[3], xh_read32(p)); p += 4;
        } while (p <= limit);
    }

    if (p < end) {
        memcpy(st->mem32, p, (size_t)(end - p));
        st->memsize = (uint32_t)(end - p);
    }
    return XXH_OK;
}

uint32_t XXH32_digest(const XXH32_state_t *st)
{
    uint32_t h;

    if (st->large_len) {
        h = xh_rotl32(st->v[0], 1) + xh_rotl32(st->v[1], 7) +
            xh_rotl32(st->v[2], 12) + xh_rotl32(st->v[3], 18);
    } else {
        h = st->v[2] /* == seed */ + P32_5;
    }
    h += st->total_len_32;
    return xh32_finalize(h, (const unsigned char *)st->mem32, st->memsize);
}

/* ------------------------------------------------------------------ */
/* XXH64                                                              */
/* ------------------------------------------------------------------ */

#define P64_1 11400714785074694791ULL
#define P64_2 14029467366897019727ULL
#define P64_3  1609587929392839161ULL
#define P64_4  9650029242287828579ULL
#define P64_5  2870177450012600261ULL

static uint64_t xh64_round(uint64_t acc, uint64_t lane)
{
    acc += lane * P64_2;
    acc  = xh_rotl64(acc, 31);
    acc *= P64_1;
    return acc;
}

static uint64_t xh64_merge(uint64_t acc, uint64_t val)
{
    val = xh64_round(0, val);
    acc ^= val;
    acc = acc * P64_1 + P64_4;
    return acc;
}

static uint64_t xh64_avalanche(uint64_t h)
{
    h ^= h >> 33;
    h *= P64_2;
    h ^= h >> 29;
    h *= P64_3;
    h ^= h >> 32;
    return h;
}

static uint64_t xh64_finalize(uint64_t h, const unsigned char *p, size_t len)
{
    len &= 31;
    while (len >= 8) {
        uint64_t const k1 = xh64_round(0, xh_read64(p));
        p += 8; len -= 8;
        h ^= k1;
        h = xh_rotl64(h, 27) * P64_1 + P64_4;
    }
    if (len >= 4) {
        h ^= (uint64_t)xh_read32(p) * P64_1;
        p += 4; len -= 4;
        h = xh_rotl64(h, 23) * P64_2 + P64_3;
    }
    while (len > 0) {
        h ^= (uint64_t)(*p++) * P64_5;
        h = xh_rotl64(h, 11) * P64_1;
        len--;
    }
    return xh64_avalanche(h);
}

uint64_t XXH64(const void *input, size_t len, uint64_t seed)
{
    const unsigned char *p = (const unsigned char *)input;
    uint64_t h;

    if (len >= 32) {
        const unsigned char *const limit = p + len - 32;
        uint64_t v1 = seed + P64_1 + P64_2;
        uint64_t v2 = seed + P64_2;
        uint64_t v3 = seed;
        uint64_t v4 = seed - P64_1;
        do {
            v1 = xh64_round(v1, xh_read64(p)); p += 8;
            v2 = xh64_round(v2, xh_read64(p)); p += 8;
            v3 = xh64_round(v3, xh_read64(p)); p += 8;
            v4 = xh64_round(v4, xh_read64(p)); p += 8;
        } while (p <= limit);

        h = xh_rotl64(v1, 1) + xh_rotl64(v2, 7) +
            xh_rotl64(v3, 12) + xh_rotl64(v4, 18);
        h = xh64_merge(h, v1);
        h = xh64_merge(h, v2);
        h = xh64_merge(h, v3);
        h = xh64_merge(h, v4);
    } else {
        h = seed + P64_5;
    }
    h += (uint64_t)len;
    return xh64_finalize(h, p, len);
}

void XXH64_reset(XXH64_state_t *st, uint64_t seed)
{
    memset(st, 0, sizeof(*st));
    st->v[0] = seed + P64_1 + P64_2;
    st->v[1] = seed + P64_2;
    st->v[2] = seed;
    st->v[3] = seed - P64_1;
}

XXH_errorcode XXH64_update(XXH64_state_t *st, const void *input, size_t len)
{
    const unsigned char *p = (const unsigned char *)input;
    const unsigned char *const end = p + len;

    if (input == NULL)
        return len ? XXH_ERROR : XXH_OK;

    st->total_len += len;

    if (st->memsize + len < 32) {
        memcpy((unsigned char *)st->mem64 + st->memsize, p, len);
        st->memsize += (uint32_t)len;
        return XXH_OK;
    }

    if (st->memsize) {
        size_t const fill = 32 - st->memsize;
        memcpy((unsigned char *)st->mem64 + st->memsize, p, fill);
        st->v[0] = xh64_round(st->v[0], xh_read64(&st->mem64[0]));
        st->v[1] = xh64_round(st->v[1], xh_read64(&st->mem64[1]));
        st->v[2] = xh64_round(st->v[2], xh_read64(&st->mem64[2]));
        st->v[3] = xh64_round(st->v[3], xh_read64(&st->mem64[3]));
        p += fill;
        st->memsize = 0;
    }

    if (p + 32 <= end) {
        const unsigned char *const limit = end - 32;
        do {
            st->v[0] = xh64_round(st->v[0], xh_read64(p)); p += 8;
            st->v[1] = xh64_round(st->v[1], xh_read64(p)); p += 8;
            st->v[2] = xh64_round(st->v[2], xh_read64(p)); p += 8;
            st->v[3] = xh64_round(st->v[3], xh_read64(p)); p += 8;
        } while (p <= limit);
    }

    if (p < end) {
        memcpy(st->mem64, p, (size_t)(end - p));
        st->memsize = (uint32_t)(end - p);
    }
    return XXH_OK;
}

uint64_t XXH64_digest(const XXH64_state_t *st)
{
    uint64_t h;

    if (st->total_len >= 32) {
        uint64_t const v1 = st->v[0], v2 = st->v[1], v3 = st->v[2], v4 = st->v[3];
        h = xh_rotl64(v1, 1) + xh_rotl64(v2, 7) +
            xh_rotl64(v3, 12) + xh_rotl64(v4, 18);
        h = xh64_merge(h, v1);
        h = xh64_merge(h, v2);
        h = xh64_merge(h, v3);
        h = xh64_merge(h, v4);
    } else {
        h = st->v[2] /* seed */ + P64_5;
    }
    h += st->total_len;
    return xh64_finalize(h, (const unsigned char *)st->mem64, (size_t)st->memsize);
}

