#ifndef LZ4BLK_H
#define LZ4BLK_H

#include <stddef.h>
#include <stdint.h>

#define LZ4_MEMORY_USAGE   14
#define LZ4_HASHLOG        (LZ4_MEMORY_USAGE - 2)
#define LZ4_HASH_SIZE_U32  (1u << LZ4_HASHLOG)

#define LZ4_MAX_INPUT_SIZE 0x7E000000  /* 2 113 929 216 bytes */
#define LZ4_ACCEL_DEFAULT  1
#define LZ4_ACCEL_MAX      65537

/* worst case expansion */
#define LZ4_COMPRESSBOUND(isize) \
    ((unsigned)(isize) > (unsigned)LZ4_MAX_INPUT_SIZE ? 0u \
     : (unsigned)(isize) + ((unsigned)(isize) / 255u) + 16u)

int LZ4_compressBound(int isize);

/* --- table addressing modes, mirrored from the reference design --- */
typedef enum { tt_cleared = 0, tt_byPtr, tt_byU32, tt_byU16 } lz4_tabletype_e;

typedef struct lz4_stream_s lz4_stream_t;
struct lz4_stream_s {
    uint32_t             hashTable[LZ4_HASH_SIZE_U32];
    const unsigned char *dictionary;
    const lz4_stream_t  *dictCtx;
    uint32_t             currentOffset;
    uint32_t             tableType;
    uint32_t             dictSize;
};

/* one-shot compression, unlimited output buffer assumed >= compressBound */
int LZ4_compress_default(const char *src, char *dst, int srcSize, int dstCapacity);
int LZ4_compress_fast(const char *src, char *dst, int srcSize, int dstCapacity, int accel);

/* stateful variants used by the frame layer */
void lz4_stream_init(lz4_stream_t *s);
int  LZ4_compress_fast_extState_fastReset(lz4_stream_t *s, const char *src, char *dst,
                                          int srcSize, int dstCapacity, int accel);
