                                int srcSize, int dstCapacity, int accel);
int  LZ4_loadDict(lz4_stream_t *s, const char *dictionary, int dictSize);
void LZ4_attach_dictionary(lz4_stream_t *working, const lz4_stream_t *dictStream);
int  LZ4_saveDict(lz4_stream_t *s, char *safeBuffer, int dictSize);

/* decompression */
int LZ4_decompress_safe(const char *src, char *dst, int compressedSize, int dstCapacity);
