                                  int dstCapacity, const char *dictStart, int dictSize);
/* dst is preceded in memory by `prefixSize` bytes of already decoded history */
int LZ4_decompress_safe_withPrefix64k(const char *src, char *dst, int compressedSize,
                                      int dstCapacity, int prefixSize);

#endif /* LZ4BLK_H */

