/*
 * lz4blk.c - LZ4 block format codec
 *
 * Independent implementation of the LZ4 block compression format, written
 * from the published format specification and the documented behaviour of
 * the reference command line tool.
 *
 * BSD 2-Clause License
 */
#include "lz4blk.h"
#include <string.h>

#ifdef __GNUC__
#  define FORCE_INLINE static inline __attribute__((always_inline))
#  define LIKELY(x)    __builtin_expect(!!(x), 1)
#  define UNLIKELY(x)  __builtin_expect(!!(x), 0)
#else
#  define FORCE_INLINE static inline
#  define LIKELY(x)    (x)
#  define UNLIKELY(x)  (x)
#endif

typedef unsigned char BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;
typedef uintptr_t uptrval;

#define MINMATCH        4
#define WILDCOPYLENGTH  8
#define LASTLITERALS    5
#define MFLIMIT         12
#define MATCH_SAFEGUARD_DISTANCE ((2 * WILDCOPYLENGTH) - MINMATCH)
#define LZ4_MIN_LENGTH  (MFLIMIT + 1)

#define KB_ (1 << 10)
#define LZ4_DISTANCE_MAX 65535
#define LZ4_DISTANCE_ABSOLUTE_MAX 65535
#define LZ4_64K_LIMIT ((64 * KB_) + (MFLIMIT - 1))

#define ML_BITS  4
#define ML_MASK  ((1u << ML_BITS) - 1)
#define RUN_BITS (8 - ML_BITS)
#define RUN_MASK ((1u << RUN_BITS) - 1)

#define LZ4_SKIP_TRIGGER 6

/* directives */
typedef enum { notLimited = 0, limitedOutput = 1, fillOutput = 2 } limit_e;
typedef enum { noDict = 0, withPrefix64k, usingExtDict, usingDictCtx } dict_e;
typedef enum { noDictIssue = 0, dictSmall } dictissue_e;

/* ------------------------------------------------------------------ */
/* unaligned / endian helpers                                          */
/* ------------------------------------------------------------------ */

typedef union { U16 u16; U32 u32; U64 u64; size_t uArch; } __attribute__((packed)) unalign_t;

static U16 rd16(const void *p) { return ((const unalign_t *)p)->u16; }
static U32 rd32(const void *p) { return ((const unalign_t *)p)->u32; }
static U64 rd64(const void *p) { return ((const unalign_t *)p)->u64; }
static size_t rdArch(const void *p) { return ((const unalign_t *)p)->uArch; }
static void wr16(void *p, U16 v) { ((unalign_t *)p)->u16 = v; }
static void wr32(void *p, U32 v) { ((unalign_t *)p)->u32 = v; }

static int is_le(void)
{
    const union { U32 u; BYTE c[4]; } one = { 1 };
    return one.c[0];
}

static U16 rdLE16(const void *p)
{
    if (is_le()) return rd16(p);
    { const BYTE *b = (const BYTE *)p; return (U16)((U16)b[0] | ((U16)b[1] << 8)); }
}

static void wrLE16(void *p, U16 v)
{
    if (is_le()) { wr16(p, v); return; }
    { BYTE *b = (BYTE *)p; b[0] = (BYTE)v; b[1] = (BYTE)(v >> 8); }
}

/* copy 8 bytes at a time, may overwrite up to 7 bytes past dstEnd */
static void wildCopy8(void *dst, const void *src, void *dstEnd)
{
    BYTE *d = (BYTE *)dst;
    const BYTE *s = (const BYTE *)src;
    do { memcpy(d, s, 8); d += 8; s += 8; } while (d < (BYTE *)dstEnd);
}

static void wildCopy32(void *dst, const void *src, void *dstEnd)
{
    BYTE *d = (BYTE *)dst;
    const BYTE *s = (const BYTE *)src;
    do {
        memcpy(d, s, 16);
        memcpy(d + 16, s + 16, 16);
        d += 32; s += 32;
    } while (d < (BYTE *)dstEnd);
}

/* number of trailing/leading zero bytes helper for LZ4_count */
static unsigned nbCommonBytes(size_t val)
{
    if (is_le()) {
#if defined(__GNUC__)
        if (sizeof(size_t) == 8) return (unsigned)__builtin_ctzll((U64)val) >> 3;
        return (unsigned)__builtin_ctz((U32)val) >> 3;
#else
        unsigned r = 0;
        while ((val & 0xFF) == 0) { val >>= 8; r++; }
        return r;
#endif
    } else {
#if defined(__GNUC__)
        if (sizeof(size_t) == 8) return (unsigned)__builtin_clzll((U64)val) >> 3;
        return (unsigned)__builtin_clz((U32)val) >> 3;
#else
        unsigned r = 0;
        size_t mask = (size_t)0xFF << ((sizeof(size_t) - 1) * 8);
        while ((val & mask) == 0) { mask >>= 8; r++; }
        return r;
#endif
    }
}

static unsigned LZ4_count(const BYTE *pIn, const BYTE *pMatch, const BYTE *pInLimit)
{
    const BYTE *const pStart = pIn;

    if (LIKELY(pIn < pInLimit - (sizeof(size_t) - 1))) {
        size_t const diff = rdArch(pMatch) ^ rdArch(pIn);
        if (!diff) {
            pIn += sizeof(size_t); pMatch += sizeof(size_t);
        } else {
            return nbCommonBytes(diff);
        }
    }

    while (LIKELY(pIn < pInLimit - (sizeof(size_t) - 1))) {
        size_t const diff = rdArch(pMatch) ^ rdArch(pIn);
        if (!diff) { pIn += sizeof(size_t); pMatch += sizeof(size_t); continue; }
        pIn += nbCommonBytes(diff);
        return (unsigned)(pIn - pStart);
    }

    if ((sizeof(size_t) == 8) && (pIn < (pInLimit - 3)) && (rd32(pMatch) == rd32(pIn))) {
        pIn += 4; pMatch += 4;
    }
    if ((pIn < (pInLimit - 1)) && (rd16(pMatch) == rd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

int LZ4_compressBound(int isize)
{
    return (int)LZ4_COMPRESSBOUND(isize);
}

/* ------------------------------------------------------------------ */
/* hashing                                                             */
/* ------------------------------------------------------------------ */

static U32 hash4(U32 sequence, lz4_tabletype_e tt)
{
    if (tt == tt_byU16)
        return (sequence * 2654435761u) >> ((MINMATCH * 8) - (LZ4_HASHLOG + 1));
    return (sequence * 2654435761u) >> ((MINMATCH * 8) - LZ4_HASHLOG);
}

static U32 hash5(U64 sequence, lz4_tabletype_e tt)
{
    const U32 hashLog = (tt == tt_byU16) ? LZ4_HASHLOG + 1 : LZ4_HASHLOG;
    if (is_le()) {
        const U64 prime5bytes = 889523592379ULL;
        return (U32)(((sequence << 24) * prime5bytes) >> (64 - hashLog));
    } else {
        const U64 prime8bytes = 11400714785074694791ULL;
        return (U32)(((sequence >> 24) * prime8bytes) >> (64 - hashLog));
    }
}

FORCE_INLINE U32 hashPosition(const void *p, lz4_tabletype_e tt)
{
    if ((sizeof(size_t) == 8) && (tt != tt_byU16)) return hash5(rd64(p), tt);
    return hash4(rd32(p), tt);
}

FORCE_INLINE void putIndexOnHash(U32 idx, U32 h, void *tableBase, lz4_tabletype_e tt)
{
    if (tt == tt_byU32) { ((U32 *)tableBase)[h] = idx; return; }
    if (tt == tt_byU16) { ((U16 *)tableBase)[h] = (U16)idx; return; }
}

FORCE_INLINE U32 getIndexOnHash(U32 h, const void *tableBase, lz4_tabletype_e tt)
{
    if (tt == tt_byU32) return ((const U32 *)tableBase)[h];
    return ((const U16 *)tableBase)[h];
}

/* ------------------------------------------------------------------ */
/* compression                                                         */
/* ------------------------------------------------------------------ */

void lz4_stream_init(lz4_stream_t *s)
{
    memset(s, 0, sizeof(*s));
}

static void prepareTable(lz4_stream_t *ctx, const int inputSize, const lz4_tabletype_e tt)
{
    if ((lz4_tabletype_e)ctx->tableType != tt_cleared) {
        if ((lz4_tabletype_e)ctx->tableType != tt
            || ((tt == tt_byU16) && ctx->currentOffset + (unsigned)inputSize >= 0xFFFFu)
            || ((tt == tt_byU32) && ctx->currentOffset > (1u << 30))
            || tt == tt_byPtr
            || inputSize >= 4 * KB_) {
            memset(ctx->hashTable, 0, sizeof(ctx->hashTable));
            ctx->currentOffset = 0;
            ctx->tableType = (U32)tt_cleared;
        }
    }

    /* leaving a gap makes stale entries fall outside the max match distance */
    if (ctx->currentOffset != 0 && tt == tt_byU32)
        ctx->currentOffset += 64 * KB_;

    ctx->dictCtx = NULL;
    ctx->dictionary = NULL;
    ctx->dictSize = 0;
}

FORCE_INLINE int lz4_compress_generic(
        lz4_stream_t *const cctx,
        const char *const src,
        char *const dst,
        const int srcSize,
        int *inputConsumed,
        const int dstCapacity,
        const limit_e outputDirective,
        const lz4_tabletype_e tableType,
        const dict_e dictDirective,
        const dictissue_e dictIssue,
        const int acceleration)
{
    int result;
    const BYTE *ip = (const BYTE *)src;

    U32 const startIndex = cctx->currentOffset;
    const BYTE *base = (const BYTE *)src - startIndex;
    const BYTE *lowLimit;

    const lz4_stream_t *dictCtx = cctx->dictCtx;
    const BYTE *const dictionary =
        (dictDirective == usingDictCtx) ? dictCtx->dictionary : cctx->dictionary;
    const U32 dictSize =
        (dictDirective == usingDictCtx) ? dictCtx->dictSize : cctx->dictSize;
    const U32 dictDelta =
        (dictDirective == usingDictCtx) ? startIndex - dictCtx->currentOffset : 0;

    int const maybe_extMem = (dictDirective == usingExtDict) || (dictDirective == usingDictCtx);
    U32 const prefixIdx = (dictDirective == withPrefix64k) ? 65536 : startIndex;
    const BYTE *const dictEnd = dictionary ? dictionary + dictSize : dictionary;
    const BYTE *anchor = (const BYTE *)src;
    const BYTE *const iend = ip + srcSize;
    const BYTE *const mflimitPlusOne = iend - MFLIMIT + 1;
    const BYTE *const matchlimit = iend - LASTLITERALS;

    const BYTE *dictBase = (dictionary == NULL) ? NULL :
        (dictDirective == usingDictCtx) ?
            dictionary + dictSize - dictCtx->currentOffset :
            dictionary + dictSize - startIndex;

    BYTE *op = (BYTE *)dst;
    BYTE *const olimit = op + dstCapacity;

    U32 offset = 0;
    U32 forwardH;

    if (outputDirective == fillOutput && dstCapacity < 1) return 0;
    if ((tableType == tt_byU16) && (srcSize >= LZ4_64K_LIMIT)) return 0;

    lowLimit = (const BYTE *)src - ((dictDirective == withPrefix64k) ? dictSize : 0);

    if (dictDirective == usingDictCtx) {
        cctx->dictCtx = NULL;
        cctx->dictSize = (U32)srcSize;
    } else {
        cctx->dictSize += (U32)srcSize;
    }
    cctx->currentOffset += (U32)srcSize;
    cctx->tableType = (U32)tableType;

    if (srcSize < LZ4_MIN_LENGTH) goto _last_literals;

    /* first byte goes into the table */
    {   U32 const h = hashPosition(ip, tableType);
        putIndexOnHash(startIndex, h, cctx->hashTable, tableType);
    }
    ip++;
    forwardH = hashPosition(ip, tableType);

    for (;;) {
        const BYTE *match;
        BYTE *token;

        /* ---- find a match ---- */
        {   const BYTE *forwardIp = ip;
            int step = 1;
            int searchMatchNb = acceleration << LZ4_SKIP_TRIGGER;
            do {
                U32 const h = forwardH;
                U32 const current = (U32)(forwardIp - base);
                U32 matchIndex = getIndexOnHash(h, cctx->hashTable, tableType);

                ip = forwardIp;
                forwardIp += step;
                step = (searchMatchNb++ >> LZ4_SKIP_TRIGGER);

                if (UNLIKELY(forwardIp > mflimitPlusOne)) goto _last_literals;

                if (dictDirective == usingDictCtx) {
                    if (matchIndex < startIndex) {
                        matchIndex = getIndexOnHash(h, dictCtx->hashTable, tt_byU32);
                        match = dictBase + matchIndex;
                        matchIndex += dictDelta;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = (const BYTE *)src;
                    }
                } else if (dictDirective == usingExtDict) {
                    if (matchIndex < startIndex) {
                        match = dictBase + matchIndex;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = (const BYTE *)src;
                    }
                } else {
                    match = base + matchIndex;
                }
                forwardH = hashPosition(forwardIp, tableType);
                putIndexOnHash(current, h, cctx->hashTable, tableType);

                if ((dictIssue == dictSmall) && (matchIndex < prefixIdx)) continue;
                if (((tableType != tt_byU16) || (LZ4_DISTANCE_MAX < LZ4_DISTANCE_ABSOLUTE_MAX))
                    && (matchIndex + LZ4_DISTANCE_MAX < current)) continue;

                if (rd32(match) == rd32(ip)) {
                    if (maybe_extMem) offset = current - matchIndex;
                    break;
                }
            } while (1);
        }

        /* ---- extend match backwards over literals ---- */
        if ((match > lowLimit) && UNLIKELY(ip[-1] == match[-1])) {
            do { ip--; match--; }
            while (((ip > anchor) & (match > lowLimit)) && (UNLIKELY(ip[-1] == match[-1])));
        }

        /* ---- encode literals ---- */
        {   unsigned const litLength = (unsigned)(ip - anchor);
            token = op++;
            if ((outputDirective == limitedOutput) &&
                UNLIKELY(op + litLength + (2 + 1 + LASTLITERALS) + (litLength / 255) > olimit)) {
                return 0;
            }
            if ((outputDirective == fillOutput) &&
                UNLIKELY(op + (litLength + 240) / 255 + litLength + 2 + 1 + MFLIMIT - MINMATCH > olimit)) {
                op--;
                goto _last_literals;
            }
            if (litLength >= RUN_MASK) {
                unsigned len = litLength - RUN_MASK;
                *token = (BYTE)(RUN_MASK << ML_BITS);
                for (; len >= 255; len -= 255) *op++ = 255;
                *op++ = (BYTE)len;
            } else {
                *token = (BYTE)(litLength << ML_BITS);
            }
            wildCopy8(op, anchor, op + litLength);
            op += litLength;
        }

_next_match:
        if ((outputDirective == fillOutput) &&
            (op + 2 /* offset */ + 1 /* token */ + MFLIMIT - MINMATCH > olimit)) {
            /* not enough room to store the match: revert */
            op = token;
            goto _last_literals;
        }

        /* ---- encode offset ---- */
        if (maybe_extMem) {
            wrLE16(op, (U16)offset); op += 2;
        } else {
            wrLE16(op, (U16)(ip - match)); op += 2;
        }

        /* ---- encode match length ---- */
        {   unsigned matchCode;

            if ((dictDirective == usingExtDict || dictDirective == usingDictCtx)
                && (lowLimit == dictionary)) {
                const BYTE *limit = ip + (dictEnd - match);
                if (limit > matchlimit) limit = matchlimit;
                matchCode = LZ4_count(ip + MINMATCH, match + MINMATCH, limit);
                ip += (size_t)matchCode + MINMATCH;
                if (ip == limit) {
                    unsigned const more = LZ4_count(limit, (const BYTE *)src, matchlimit);
                    matchCode += more;
                    ip += more;
                }
            } else {
                matchCode = LZ4_count(ip + MINMATCH, match + MINMATCH, matchlimit);
                ip += (size_t)matchCode + MINMATCH;
            }

            if (outputDirective &&
                UNLIKELY(op + (1 + LASTLITERALS) + (matchCode + 240) / 255 > olimit)) {
                if (outputDirective == fillOutput) {
                    /* reduce the match to fit */
                    U32 newMatchCode = 15 /* in token */ - 1 /* to avoid needing a zero byte */
                                     + ((U32)(olimit - op) - 1 - LASTLITERALS) * 255;
                    ip -= matchCode - newMatchCode;
                    matchCode = newMatchCode;
                    if (UNLIKELY(ip <= (const BYTE *)src)) return 0;
                } else {
                    return 0;
                }
            }
            if (matchCode >= ML_MASK) {
                *token += (BYTE)ML_MASK;
                matchCode -= ML_MASK;
                wr32(op, 0xFFFFFFFFu);
                while (matchCode >= 4 * 255) {
                    op += 4;
                    wr32(op, 0xFFFFFFFFu);
                    matchCode -= 4 * 255;
                }
                op += matchCode / 255;
                *op++ = (BYTE)(matchCode % 255);
            } else {
                *token += (BYTE)matchCode;
            }
        }

        anchor = ip;

        if (ip >= mflimitPlusOne) break;

        /* fill table for position ip-2 */
        {   U32 const pos = (U32)(ip - 2 - base);
            putIndexOnHash(pos, hashPosition(ip - 2, tableType), cctx->hashTable, tableType);
        }

        /* test next position immediately */
        {   U32 const h = hashPosition(ip, tableType);
            U32 const current = (U32)(ip - base);
            U32 matchIndex = getIndexOnHash(h, cctx->hashTable, tableType);
            if (dictDirective == usingDictCtx) {
                if (matchIndex < startIndex) {
                    matchIndex = getIndexOnHash(h, dictCtx->hashTable, tt_byU32);
                    match = dictBase + matchIndex;
                    lowLimit = dictionary;
                    matchIndex += dictDelta;
                } else {
                    match = base + matchIndex;
                    lowLimit = (const BYTE *)src;
                }
            } else if (dictDirective == usingExtDict) {
                if (matchIndex < startIndex) {
                    match = dictBase + matchIndex;
                    lowLimit = dictionary;
                } else {
                    match = base + matchIndex;
                    lowLimit = (const BYTE *)src;
                }
            } else {
                match = base + matchIndex;
            }
            putIndexOnHash(current, h, cctx->hashTable, tableType);
            if (((dictIssue == dictSmall) ? (matchIndex >= prefixIdx) : 1)
                && (((tableType == tt_byU16) && (LZ4_DISTANCE_MAX == LZ4_DISTANCE_ABSOLUTE_MAX))
                        ? 1 : (matchIndex + LZ4_DISTANCE_MAX >= current))
                && (rd32(match) == rd32(ip))) {
                token = op++;
                *token = 0;
                if (maybe_extMem) offset = current - matchIndex;
                goto _next_match;
            }
        }

        forwardH = hashPosition(++ip, tableType);
    }

_last_literals:
    {   size_t lastRun = (size_t)(iend - anchor);
        if (outputDirective &&
            (op + lastRun + 1 + ((lastRun + 255 - RUN_MASK) / 255) > olimit)) {
            if (outputDirective == fillOutput) {
                size_t avail = (size_t)(olimit - op);
                if (avail == 0) return 0;
                lastRun = avail - 1;
                if (lastRun >= RUN_MASK) {
                    /* room for the token plus the length continuation bytes */
                    size_t extra = (lastRun - RUN_MASK) / 255 + 1;
                    while (lastRun + 1 + extra > avail) {
                        lastRun--;
                        extra = (lastRun >= RUN_MASK) ? (lastRun - RUN_MASK) / 255 + 1 : 0;
                    }
                }
            } else {
                return 0;
            }
        }
        if (lastRun >= RUN_MASK) {
            size_t accumulator = lastRun - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRun << ML_BITS);
        }
        memcpy(op, anchor, lastRun);
        ip = anchor + lastRun;
        op += lastRun;
    }

    if (outputDirective == fillOutput && inputConsumed)
        *inputConsumed = (int)((const char *)ip - src);

    result = (int)((char *)op - dst);
    return result;
}

/* --- public entry points --- */

static int compress_oneshot(lz4_stream_t *ctx, const char *src, char *dst,
                            int srcSize, int dstCapacity, int accel)
{
    if (accel < 1) accel = LZ4_ACCEL_DEFAULT;
    if (accel > LZ4_ACCEL_MAX) accel = LZ4_ACCEL_MAX;

    if (dstCapacity >= LZ4_compressBound(srcSize)) {
        if (srcSize < LZ4_64K_LIMIT)
            return lz4_compress_generic(ctx, src, dst, srcSize, NULL, 0, notLimited,
                                        tt_byU16, noDict, noDictIssue, accel);
        return lz4_compress_generic(ctx, src, dst, srcSize, NULL, 0, notLimited,
                                    tt_byU32, noDict, noDictIssue, accel);
    } else {
        if (srcSize < LZ4_64K_LIMIT)
            return lz4_compress_generic(ctx, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                        tt_byU16, noDict, noDictIssue, accel);
        return lz4_compress_generic(ctx, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                    tt_byU32, noDict, noDictIssue, accel);
    }
}

int LZ4_compress_fast(const char *src, char *dst, int srcSize, int dstCapacity, int accel)
{
    lz4_stream_t ctx;
    lz4_stream_init(&ctx);
    return compress_oneshot(&ctx, src, dst, srcSize, dstCapacity, accel);
}

int LZ4_compress_default(const char *src, char *dst, int srcSize, int dstCapacity)
{
    return LZ4_compress_fast(src, dst, srcSize, dstCapacity, 1);
}

int LZ4_compress_fast_extState_fastReset(lz4_stream_t *ctx, const char *src, char *dst,
                                         int srcSize, int dstCapacity, int accel)
{
    if (accel < 1) accel = LZ4_ACCEL_DEFAULT;
    if (accel > LZ4_ACCEL_MAX) accel = LZ4_ACCEL_MAX;

    if (dstCapacity >= LZ4_compressBound(srcSize)) {
        if (srcSize < LZ4_64K_LIMIT) {
            prepareTable(ctx, srcSize, tt_byU16);
            if (ctx->currentOffset)
                return lz4_compress_generic(ctx, src, dst, srcSize, NULL, 0, notLimited,
                                            tt_byU16, noDict, dictSmall, accel);
            return lz4_compress_generic(ctx, src, dst, srcSize, NULL, 0, notLimited,
                                        tt_byU16, noDict, noDictIssue, accel);
        } else {
            prepareTable(ctx, srcSize, tt_byU32);
            return lz4_compress_generic(ctx, src, dst, srcSize, NULL, 0, notLimited,
                                        tt_byU32, noDict, noDictIssue, accel);
        }
    } else {
        if (srcSize < LZ4_64K_LIMIT) {
            prepareTable(ctx, srcSize, tt_byU16);
            if (ctx->currentOffset)
                return lz4_compress_generic(ctx, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                            tt_byU16, noDict, dictSmall, accel);
            return lz4_compress_generic(ctx, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                        tt_byU16, noDict, noDictIssue, accel);
        } else {
            prepareTable(ctx, srcSize, tt_byU32);
            return lz4_compress_generic(ctx, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                        tt_byU32, noDict, noDictIssue, accel);
        }
    }
}

/* ---- streaming ---- */

static void renormDictT(lz4_stream_t *s, int nextSize)
{
    if (s->currentOffset + (unsigned)nextSize > 0x80000000u) {   /* fixed point index overflow */
        U32 const delta = s->currentOffset - 64 * KB_;
        const BYTE *dictEnd = s->dictionary + s->dictSize;
        int i;
        for (i = 0; i < (int)LZ4_HASH_SIZE_U32; i++) {
            if (s->hashTable[i] < delta) s->hashTable[i] = 0;
            else s->hashTable[i] -= delta;
        }
        s->currentOffset = 64 * KB_;
        if (s->dictSize > 64 * KB_) s->dictSize = 64 * KB_;
        s->dictionary = dictEnd - s->dictSize;
    }
}

int LZ4_loadDict(lz4_stream_t *s, const char *dictionary, int dictSize)
{
    const BYTE *p = (const BYTE *)dictionary;
    const BYTE *const dictEnd = p + dictSize;

    prepareTable(s, 0, tt_byU32);
    /* prepareTable clears state; make sure the table itself is zeroed */
    memset(s->hashTable, 0, sizeof(s->hashTable));
    s->currentOffset = 0;
    s->tableType = (U32)tt_byU32;

    if (dictSize < (int)MINMATCH) {
        s->dictionary = NULL;
        s->dictSize = 0;
        return 0;
    }

    if (dictEnd - p > 64 * KB_) p = dictEnd - 64 * KB_;
    s->currentOffset += 64 * KB_;
    s->dictionary = p;
    s->dictSize = (U32)(dictEnd - p);

    {   const BYTE *base = p - s->currentOffset;
        const BYTE *const idxLimit = dictEnd - MINMATCH + 1;
        while (p <= idxLimit - 8) {
            U32 const idx = (U32)(p - base);
            putIndexOnHash(idx, hashPosition(p, tt_byU32), s->hashTable, tt_byU32);
            p += 3;
        }
    }
    return (int)s->dictSize;
}

void LZ4_attach_dictionary(lz4_stream_t *working, const lz4_stream_t *dictStream)
{
    working->dictCtx = NULL;
    if (dictStream != NULL) {
        if (dictStream->dictSize > 0) working->dictCtx = dictStream;
    }
}

static void loadDictOnly(lz4_stream_t *s)
{
    (void)s;
}

int LZ4_compress_fast_continue(lz4_stream_t *s, const char *src, char *dst,
                              int srcSize, int dstCapacity, int accel)
{
    const lz4_tabletype_e tableType = tt_byU32;
    const char *dictEnd = s->dictSize ? (const char *)s->dictionary + s->dictSize : NULL;

    loadDictOnly(s);
    renormDictT(s, srcSize);
    if (accel < 1) accel = LZ4_ACCEL_DEFAULT;
    if (accel > LZ4_ACCEL_MAX) accel = LZ4_ACCEL_MAX;

    /* a dictionary shorter than a hash unit is useless */
    if ((s->dictSize < 4) && (dictEnd != src) && (srcSize > 0) && (s->dictCtx == NULL)) {
        s->dictSize = 0;
        s->dictionary = (const BYTE *)src;
        dictEnd = src;
    }

    /* overlapping input / dictionary */
    {   const char *const sourceEnd = src + srcSize;
        if ((sourceEnd > (const char *)s->dictionary) && (sourceEnd < dictEnd)) {
            s->dictSize = (U32)(dictEnd - sourceEnd);
            if (s->dictSize > 64 * KB_) s->dictSize = 64 * KB_;
            if (s->dictSize < 4) s->dictSize = 0;
            s->dictionary = (const BYTE *)dictEnd - s->dictSize;
        }
    }

    /* prefix mode: source immediately follows the dictionary in memory */
    if (dictEnd == src) {
        if ((s->dictSize < 64 * KB_) && (s->dictSize < s->currentOffset))
            return lz4_compress_generic(s, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                        tableType, withPrefix64k, dictSmall, accel);
        return lz4_compress_generic(s, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                    tableType, withPrefix64k, noDictIssue, accel);
    }

    /* external dictionary */
    if (s->dictCtx != NULL) {
        /* small inputs benefit from copying the dictionary context table */
        if (srcSize > 4 * KB_) {
            memcpy(s->hashTable, s->dictCtx->hashTable, sizeof(s->hashTable));
            s->currentOffset += s->dictCtx->currentOffset;
            s->dictionary = s->dictCtx->dictionary;
            s->dictSize = s->dictCtx->dictSize;
            s->dictCtx = NULL;
            return lz4_compress_generic(s, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                        tableType, usingExtDict, noDictIssue, accel);
        }
        return lz4_compress_generic(s, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                    tableType, usingDictCtx, noDictIssue, accel);
    }

    if (s->dictSize < 64 * KB_ && s->dictSize < s->currentOffset)
        return lz4_compress_generic(s, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                    tableType, usingExtDict, dictSmall, accel);
    return lz4_compress_generic(s, src, dst, srcSize, NULL, dstCapacity, limitedOutput,
                                tableType, usingExtDict, noDictIssue, accel);
}

int LZ4_saveDict(lz4_stream_t *s, char *safeBuffer, int dictSize)
{
    const BYTE *const previousDictEnd = s->dictionary + s->dictSize;

    if ((U32)dictSize > 64 * KB_) dictSize = 64 * KB_;
    if ((U32)dictSize > s->dictSize) dictSize = (int)s->dictSize;

    if (safeBuffer == NULL) return dictSize;
    if (dictSize > 0)
        memmove(safeBuffer, previousDictEnd - dictSize, (size_t)dictSize);

    s->dictionary = (const BYTE *)safeBuffer;
    s->dictSize = (U32)dictSize;
    return dictSize;
}

/* ------------------------------------------------------------------ */
/* decompression                                                       */
/* ------------------------------------------------------------------ */

static const unsigned inc32table[8] = { 0, 1, 2, 1, 0, 4, 4, 4 };
static const int      dec64table[8] = { 0, 0, 0, -1, -4, 1, 2, 3 };

