    const BYTE *const iend = ip + srcSize;

    BYTE *op = (BYTE *)dst;
    BYTE *const oend = op + outputSize;

    const BYTE *const dictEnd = (dictStart == NULL) ? NULL : dictStart + dictSize;
    size_t const extraHistory = (dict == d_usingExtDict) ? dictSize : 0;

    if (UNLIKELY(srcSize == 0)) return -1;
    if (UNLIKELY(outputSize == 0)) {
        if ((srcSize == 1) && (*ip == 0)) return 0;
        return -1;
    }

    for (;;) {
        unsigned const token = *ip++;
        size_t length = (size_t)(token >> ML_BITS);

        /* ---- literals ---- */
        if (length == RUN_MASK) {
            unsigned s;
            do {
                if (UNLIKELY(ip >= iend)) return -1;
                s = *ip++;
                length += s;
                if (UNLIKELY(length > (size_t)0x7FFFFFFF)) return -1;
            } while (s == 255);
        }

        if (UNLIKELY((size_t)(iend - ip) < length)) return -1;
        if (UNLIKELY((size_t)(oend - op) < length)) return -1;
        if (length) {
            if ((size_t)(oend - op) >= length + WILDCOPYLENGTH &&
                (size_t)(iend - ip) >= length + WILDCOPYLENGTH) {
                wildCopy8(op, ip, op + length);
            } else {
                memcpy(op, ip, length);
            }
            ip += length;
            op += length;
        }

        if (ip == iend) break;      /* a block always ends on a literal run */

        /* ---- match ---- */
        if (UNLIKELY((size_t)(iend - ip) < 2)) return -1;
        {   size_t const offset = rdLE16(ip);
            const BYTE *match;
            ip += 2;

            length = token & ML_MASK;
            if (length == ML_MASK) {
                unsigned s;
                do {
                    if (UNLIKELY(ip >= iend)) return -1;
                    s = *ip++;
                    length += s;
                    if (UNLIKELY(length > (size_t)0x7FFFFFFF)) return -1;
                } while (s == 255);
