            if (UNLIKELY((size_t)(op - lowPrefix) + extraHistory < offset)) return -1;
            if (UNLIKELY((size_t)(oend - op) < length)) return -1;

            match = op - offset;

            if ((dict == d_usingExtDict) && (match < lowPrefix)) {
