static int lz4_decompress_generic(
        const char *const src,
        char *const dst,
        int srcSize,
        int outputSize,
        earlyend_e endOnInput,
        dvariant_e dict,
        const BYTE *const lowPrefix,       /* always <= dst */
        const BYTE *const dictStart,
        const size_t dictSize)
{
    const BYTE *ip = (const BYTE *)src;
    const BYTE *const iend = ip + srcSize;

    BYTE *op = (BYTE *)dst;
    BYTE *const oend = op + outputSize;
    BYTE *cpy;

    const BYTE *const dictEnd = (dictStart == NULL) ? NULL : dictStart + dictSize;

    const int checkOffset = (dictSize < 64 * KB_);

    (void)endOnInput;

    if (UNLIKELY(outputSize == 0)) {
        /* an empty output buffer only accepts the empty-literal token */
        if ((srcSize == 1) && (*ip == 0)) return 0;
        return -1;
    }
    if (UNLIKELY(srcSize == 0)) return -1;

    /* main loop */
    while (1) {
        unsigned token;
        size_t length;

        token = *ip++;
        length = (size_t)(token >> ML_BITS);

        /* ---- literals ---- */
        if (length == RUN_MASK) {
            unsigned s;
            do {
                if (UNLIKELY(ip >= iend - 1)) return -1;
                s = *ip++;
                length += s;
            } while (s == 255);
            if (UNLIKELY((uptrval)(op) + length < (uptrval)(op))) return -1; /* overflow */
        }

        cpy = op + length;
        if ((size_t)(iend - ip) < length) return -1;
        if ((size_t)(oend - op) < length) return -1;
        memmove(op, ip, length);
        ip += length;
        op = cpy;

        if (ip == iend) {
            /* end of block: the last sequence must be literals only */
            break;
        }

        /* ---- match ---- */
        {   size_t offset;
            if ((size_t)(iend - ip) < 2) return -1;
            offset = rdLE16(ip); ip += 2;

            length = token & ML_MASK;
            if (length == ML_MASK) {
                unsigned s;
                do {
                    if (UNLIKELY(ip >= iend)) return -1;
                    s = *ip++;
                    length += s;
                    if (UNLIKELY(length > (size_t)0x7FFFFFFF)) return -1;
                } while (s == 255);
            }
            length += MINMATCH;

            if (offset == 0) return -1;
            if (checkOffset && ((size_t)(op - lowPrefix) + dictSize < offset)) return -1;
            if ((size_t)(op - lowPrefix) + dictSize < offset) return -1;
            if ((size_t)(oend - op) < length) return -1;

            {   const BYTE *match = op - offset;

                if ((dict == d_usingExtDict) && (match < lowPrefix)) {
                    size_t const fromDict = (size_t)(lowPrefix - match);
                    if (fromDict > dictSize) return -1;
                    {   const BYTE *dmatch = dictEnd - fromDict;
