#ifndef LZ4HC_H
#define LZ4HC_H

#include <stddef.h>
#include <stdint.h>

#define LZ4HC_CLEVEL_MIN      2
#define LZ4HC_CLEVEL_DEFAULT  9
#define LZ4HC_CLEVEL_OPT_MIN 10
#define LZ4HC_CLEVEL_MAX     12

#define LZ4HC_DICTIONARY_LOGSIZE 16
#define LZ4HC_MAXD  (1 << LZ4HC_DICTIONARY_LOGSIZE)
#define LZ4HC_MAXD_MASK (LZ4HC_MAXD - 1)

#define LZ4HC_HASH_LOG 15
#define LZ4HC_HASHTABLESIZE (1 << LZ4HC_HASH_LOG)
#define LZ4HC_HASH_MASK (LZ4HC_HASHTABLESIZE - 1)

typedef struct lz4hc_ctx_s lz4hc_ctx_t;
struct lz4hc_ctx_s {
    uint32_t hashTable[LZ4HC_HASHTABLESIZE];
    uint16_t chainTable[LZ4HC_MAXD];
    const unsigned char *end;          /* next block continues here */
    const unsigned char *prefixStart;  /* indexes are relative to this */
    const unsigned char *dictStart;    /* alternate reference for extDict */
    uint32_t dictLimit;
    uint32_t lowLimit;
    uint32_t nextToUpdate;
    short    compressionLevel;
    signed char favorDecSpeed;
    signed char dirty;
    const lz4hc_ctx_t *dictCtx;
};

void LZ4_initStreamHC(lz4hc_ctx_t *s);
void LZ4_setCompressionLevel(lz4hc_ctx_t *s, int level);
