/*
 * lz4hc.c - LZ4 high compression variant
 *
 * Independent implementation of the LZ4 "HC" match finder and parsers.
 * BSD 2-Clause License
 */
#include "lz4hc.h"
#include "lz4blk.h"
#include <string.h>

#ifdef __GNUC__
#  define FORCE_INLINE static inline __attribute__((always_inline))
#  define LIKELY(x)    __builtin_expect(!!(x), 1)
#  define UNLIKELY(x)  __builtin_expect(!!(x), 0)
#else
#  define FORCE_INLINE static inline
#  define LIKELY(x)    (x)
#  define UNLIKELY(x)  (x)
#endif

typedef unsigned char BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;
typedef size_t   reg_t;

#define MINMATCH 4
#define WILDCOPYLENGTH 8
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_MIN_LENGTH (MFLIMIT + 1)
#define ML_BITS  4
#define ML_MASK  ((1u << ML_BITS) - 1)
#define RUN_BITS (8 - ML_BITS)
#define RUN_MASK ((1u << RUN_BITS) - 1)
#define KB_ (1 << 10)
#define LZ4_DISTANCE_MAX 65535
#define OPTIMAL_ML ((int)((ML_MASK - 1) + MINMATCH))
#define LZ4_OPT_NUM (1 << 12)

#define MIN_(a,b) ((a) < (b) ? (a) : (b))
#define MAX_(a,b) ((a) > (b) ? (a) : (b))

typedef enum { notLimited = 0, limitedOutput = 1, fillOutput = 2 } limit_e;
typedef enum { noDictCtx = 0, usingDictCtxHc } dictctx_e;
typedef enum { favorCompressionRatio = 0, favorDecompressionSpeed } hcfavor_e;
typedef enum { rep_untested, rep_not, rep_confirmed } repeat_e;

/* ------------------------------------------------------------------ */
/* unaligned access                                                    */
/* ------------------------------------------------------------------ */

typedef union { U16 u16; U32 u32; reg_t uArch; } __attribute__((packed)) unalign2_t;
static U16   hrd16(const void *p) { return ((const unalign2_t *)p)->u16; }
static U32   hrd32(const void *p) { return ((const unalign2_t *)p)->u32; }
static reg_t hrdArch(const void *p) { return ((const unalign2_t *)p)->uArch; }
static void  hwr16(void *p, U16 v) { ((unalign2_t *)p)->u16 = v; }

static int hc_isLE(void)
{
    const union { U32 u; BYTE c[4]; } one = { 1 };
    return one.c[0];
}

static void hwrLE16(void *p, U16 v)
{
    if (hc_isLE()) { hwr16(p, v); return; }
    { BYTE *b = (BYTE *)p; b[0] = (BYTE)v; b[1] = (BYTE)(v >> 8); }
}

static unsigned hc_nbCommonBytes(reg_t val)
{
    if (hc_isLE()) {
        if (sizeof(reg_t) == 8) return (unsigned)__builtin_ctzll((U64)val) >> 3;
        return (unsigned)__builtin_ctz((U32)val) >> 3;
    } else {
        if (sizeof(reg_t) == 8) return (unsigned)__builtin_clzll((U64)val) >> 3;
        return (unsigned)__builtin_clz((U32)val) >> 3;
    }
}

static unsigned hc_count(const BYTE *pIn, const BYTE *pMatch, const BYTE *pInLimit)
{
    const BYTE *const pStart = pIn;

    if (LIKELY(pIn < pInLimit - (sizeof(reg_t) - 1))) {
        reg_t const diff = hrdArch(pMatch) ^ hrdArch(pIn);
        if (!diff) { pIn += sizeof(reg_t); pMatch += sizeof(reg_t); }
        else return hc_nbCommonBytes(diff);
    }
    while (LIKELY(pIn < pInLimit - (sizeof(reg_t) - 1))) {
        reg_t const diff = hrdArch(pMatch) ^ hrdArch(pIn);
        if (!diff) { pIn += sizeof(reg_t); pMatch += sizeof(reg_t); continue; }
        pIn += hc_nbCommonBytes(diff);
        return (unsigned)(pIn - pStart);
    }
    if ((sizeof(reg_t) == 8) && (pIn < (pInLimit - 3)) && (hrd32(pMatch) == hrd32(pIn))) {
        pIn += 4; pMatch += 4;
    }
    if ((pIn < (pInLimit - 1)) && (hrd16(pMatch) == hrd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

static void hc_wildCopy8(void *dst, const void *src, void *dstEnd)
{
    BYTE *d = (BYTE *)dst;
    const BYTE *s = (const BYTE *)src;
    do { memcpy(d, s, 8); d += 8; s += 8; } while (d < (BYTE *)dstEnd);
}

/* ------------------------------------------------------------------ */
/* chain table                                                         */
/* ------------------------------------------------------------------ */

#define HASH_FUNCTION(i) (((i) * 2654435761u) >> ((MINMATCH * 8) - LZ4HC_HASH_LOG))
#define DELTANEXTU16(table, pos) table[(U16)(pos)]

static U32 hc_hashPtr(const void *ptr) { return HASH_FUNCTION(hrd32(ptr)); }

static void LZ4HC_clearTables(lz4hc_ctx_t *hc4)
{
    memset(hc4->hashTable, 0, sizeof(hc4->hashTable));
    memset(hc4->chainTable, 0xFF, sizeof(hc4->chainTable));
}

static void LZ4HC_init_internal(lz4hc_ctx_t *hc4, const BYTE *start)
{
    size_t const bufferSize = (size_t)(hc4->end - hc4->prefixStart);
    size_t newStartingOffset = bufferSize + hc4->dictLimit;

    if (newStartingOffset > (size_t)(1 << 30)) {
        LZ4HC_clearTables(hc4);
        newStartingOffset = 0;
    }
    newStartingOffset += 64 * KB_;
    hc4->nextToUpdate = (U32)newStartingOffset;
    hc4->prefixStart = start;
    hc4->end = start;
    hc4->dictStart = start;
    hc4->dictLimit = (U32)newStartingOffset;
    hc4->lowLimit = (U32)newStartingOffset;
}

FORCE_INLINE void LZ4HC_Insert(lz4hc_ctx_t *hc4, const BYTE *ip)
{
    U16 *const chainTable = hc4->chainTable;
    U32 *const hashTable = hc4->hashTable;
    const BYTE *const prefixPtr = hc4->prefixStart;
    U32 const prefixIdx = hc4->dictLimit;
    U32 const target = (U32)(ip - prefixPtr) + prefixIdx;
    U32 idx = hc4->nextToUpdate;

    while (idx < target) {
        U32 const h = hc_hashPtr(prefixPtr + idx - prefixIdx);
        size_t delta = idx - hashTable[h];
        if (delta > LZ4_DISTANCE_MAX) delta = LZ4_DISTANCE_MAX;
        DELTANEXTU16(chainTable, idx) = (U16)delta;
        hashTable[h] = idx;
        idx++;
    }
    hc4->nextToUpdate = target;
}

/* count matching bytes backwards; returns a negative number */
static int LZ4HC_countBack(const BYTE *const ip, const BYTE *const match,
                           const BYTE *const iMin, const BYTE *const mMin)
{
    int back = 0;
    int const min = (int)MAX_(iMin - ip, mMin - match);
    while ((back > min) && (ip[back - 1] == match[back - 1])) back--;
    return back;
}

static unsigned LZ4HC_countPattern(const BYTE *ip, const BYTE *const iEnd, U32 const pattern32)
{
    const BYTE *const iStart = ip;
    reg_t const pattern = (sizeof(pattern) == 8) ?
        (reg_t)pattern32 + (((reg_t)pattern32) << (sizeof(pattern) * 4)) : (reg_t)pattern32;

    while (LIKELY(ip < iEnd - (sizeof(pattern) - 1))) {
        reg_t const diff = hrdArch(ip) ^ pattern;
        if (!diff) { ip += sizeof(pattern); continue; }
        ip += hc_nbCommonBytes(diff);
        return (unsigned)(ip - iStart);
    }

    if (hc_isLE()) {
        reg_t patternByte = pattern;
        while ((ip < iEnd) && (*ip == (BYTE)patternByte)) { ip++; patternByte >>= 8; }
    } else {
        U32 bitOffset = (sizeof(pattern) * 8) - 8;
        while (ip < iEnd) {
            BYTE const byte = (BYTE)(pattern >> bitOffset);
            if (*ip != byte) break;
            ip++; bitOffset -= 8;
        }
    }
    return (unsigned)(ip - iStart);
}

static unsigned LZ4HC_reverseCountPattern(const BYTE *ip, const BYTE *const iLow, U32 pattern)
{
    const BYTE *const iStart = ip;

    while (LIKELY(ip >= iLow + 4)) {
        if (hrd32(ip - 4) != pattern) break;
        ip -= 4;
    }
    {   const BYTE *bytePtr = (const BYTE *)(&pattern) + 3;
        while (LIKELY(ip > iLow)) {
            if (ip[-1] != *bytePtr) break;
            ip--; bytePtr--;
        }
    }
    return (unsigned)(iStart - ip);
}

/* rotate a 4-byte pattern by `rotate` bytes */
static U32 LZ4HC_rotatePattern(size_t rotate, U32 pattern)
{
    size_t const bitsToRotate = (rotate & (sizeof(pattern) - 1)) << 3;
    if (bitsToRotate == 0) return pattern;
    return ((pattern) >> bitsToRotate) | ((pattern) << (32 - bitsToRotate));
}

/* not enough room to store a whole pattern within the dictionary tail */
static int LZ4HC_protectDictEnd(U32 const dictLimit, U32 const matchIndex)
{
    return ((U32)((dictLimit - 1) - matchIndex) >= 3);
}

/* ------------------------------------------------------------------ */
/* match search                                                        */
/* ------------------------------------------------------------------ */

FORCE_INLINE int
LZ4HC_InsertAndGetWiderMatch(
        lz4hc_ctx_t *const hc4,
        const BYTE *const ip,
        const BYTE *const iLowLimit,
        const BYTE *const iHighLimit,
        int longest,
        const BYTE **matchpos,
        const BYTE **startpos,
        const int maxNbAttempts,
        const int patternAnalysis,
        const int chainSwap,
        const dictctx_e dict,
        const hcfavor_e favorDecSpeed)
{
    U16 *const chainTable = hc4->chainTable;
    U32 *const hashTable = hc4->hashTable;
    const lz4hc_ctx_t *const dictCtx = hc4->dictCtx;
    const BYTE *const prefixPtr = hc4->prefixStart;
    const U32 prefixIdx = hc4->dictLimit;
    const U32 ipIndex = (U32)(ip - prefixPtr) + prefixIdx;
    const int withinStartDistance = (hc4->lowLimit + (LZ4_DISTANCE_MAX + 1) > ipIndex);
    const U32 lowestMatchIndex = (withinStartDistance) ? hc4->lowLimit : ipIndex - LZ4_DISTANCE_MAX;
    const BYTE *const dictStart = hc4->dictStart;
    const U32 dictIdx = hc4->lowLimit;
    const BYTE *const dictEnd = dictStart + prefixIdx - dictIdx;
    int const lookBackLength = (int)(ip - iLowLimit);
    int nbAttempts = maxNbAttempts;
    U32 matchChainPos = 0;
    U32 const pattern = hrd32(ip);
    U32 matchIndex;
    repeat_e repeat = rep_untested;
    size_t srcPatternLength = 0;

    LZ4HC_Insert(hc4, ip);
    matchIndex = hashTable[hc_hashPtr(ip)];

    while ((matchIndex >= lowestMatchIndex) && (nbAttempts > 0)) {
        int matchLength = 0;
        nbAttempts--;
        if (favorDecSpeed && (ipIndex - matchIndex < 8)) {
            /* intentionally skip very short offsets */
        } else if (matchIndex >= prefixIdx) {   /* within current prefix */
            const BYTE *const matchPtr = prefixPtr + (matchIndex - prefixIdx);
            if (hrd16(iLowLimit + longest - 1) == hrd16(matchPtr - lookBackLength + longest - 1)) {
                if (hrd32(matchPtr) == pattern) {
                    int const back = lookBackLength ? LZ4HC_countBack(ip, matchPtr, iLowLimit, prefixPtr) : 0;
                    matchLength = MINMATCH + (int)hc_count(ip + MINMATCH, matchPtr + MINMATCH, iHighLimit);
                    matchLength -= back;
                    if (matchLength > longest) {
                        longest = matchLength;
                        *matchpos = matchPtr + back;
                        *startpos = ip + back;
                    }
                }
            }
        } else {   /* within the external dictionary */
            const BYTE *const matchPtr = dictStart + (matchIndex - dictIdx);
            if (LIKELY(matchIndex <= prefixIdx - 4) && (hrd32(matchPtr) == pattern)) {
                int back = 0;
                const BYTE *vLimit = ip + (prefixIdx - matchIndex);
                if (vLimit > iHighLimit) vLimit = iHighLimit;
                matchLength = (int)hc_count(ip + MINMATCH, matchPtr + MINMATCH, vLimit) + MINMATCH;
                if ((ip + matchLength == vLimit) && (vLimit < iHighLimit))
                    matchLength += (int)hc_count(ip + matchLength, prefixPtr, iHighLimit);
                back = lookBackLength ? LZ4HC_countBack(ip, matchPtr, iLowLimit, dictStart) : 0;
                matchLength -= back;
                if (matchLength > longest) {
                    longest = matchLength;
                    *matchpos = prefixPtr - prefixIdx + matchIndex + back;
                    *startpos = ip + back;
                }
            }
        }

        if (chainSwap && matchLength == longest) {   /* select a better chain */
            if (matchIndex + (U32)longest <= ipIndex) {
                int const kTrigger = 4;
                U32 distanceToNextMatch = 1;
                int const end = longest - MINMATCH + 1;
                int step = 1;
                int accel = 1 << kTrigger;
                int pos;
                for (pos = 0; pos < end; pos += step) {
                    U32 const candidateDist = DELTANEXTU16(chainTable, matchIndex + (U32)pos);
                    step = (accel++ >> kTrigger);
                    if (candidateDist > distanceToNextMatch) {
                        distanceToNextMatch = candidateDist;
                        matchChainPos = (U32)pos;
                        accel = 1 << kTrigger;
                    }
                }
                if (distanceToNextMatch > 1) {
                    if (distanceToNextMatch > matchIndex) break;   /* avoid overflow */
                    matchIndex -= distanceToNextMatch;
                    continue;
                }
            }
        }

        {   U32 const distNextMatch = DELTANEXTU16(chainTable, matchIndex);
            if (patternAnalysis && distNextMatch == 1 && matchChainPos == 0) {
                U32 const matchCandidateIdx = matchIndex - 1;
                /* may be a repeated pattern */
                if (repeat == rep_untested) {
                    if (((pattern & 0xFFFF) == (pattern >> 16))
                        & ((pattern & 0xFF) == (pattern >> 24))) {
                        repeat = rep_confirmed;
                        srcPatternLength = LZ4HC_countPattern(ip + sizeof(pattern), iHighLimit, pattern) + sizeof(pattern);
                    } else {
                        repeat = rep_not;
                    }
                }
                if ((repeat == rep_confirmed) && (matchCandidateIdx >= lowestMatchIndex)
                    && LZ4HC_protectDictEnd(prefixIdx, matchCandidateIdx)) {
                    const int extDict = matchCandidateIdx < prefixIdx;
                    const BYTE *const matchPtr = extDict ? dictStart + (matchCandidateIdx - dictIdx)
                                                         : prefixPtr + (matchCandidateIdx - prefixIdx);
                    if (hrd32(matchPtr) == pattern) {
                        const BYTE *const iLimit = extDict ? dictEnd : iHighLimit;
                        size_t forwardPatternLength =
                            LZ4HC_countPattern(matchPtr + sizeof(pattern), iLimit, pattern) + sizeof(pattern);
                        if (extDict && matchPtr + forwardPatternLength == iLimit) {
                            U32 const rotatedPattern = LZ4HC_rotatePattern(forwardPatternLength, pattern);
                            forwardPatternLength += LZ4HC_countPattern(prefixPtr, iHighLimit, rotatedPattern);
                        }
                        {   const BYTE *const lowestMatchPtr = extDict ? dictStart : prefixPtr;
                            size_t backLength = LZ4HC_reverseCountPattern(matchPtr, lowestMatchPtr, pattern);
                            size_t currentSegmentLength;
                            if (!extDict && (matchPtr - backLength == prefixPtr) && (dictIdx < prefixIdx)) {
                                U32 const rotatedPattern = LZ4HC_rotatePattern((U32)(0 - (int)backLength), pattern);
                                backLength += LZ4HC_reverseCountPattern(dictEnd, dictStart, rotatedPattern);
                            }
                            /* do not go further back than lowestMatchIndex */
                            backLength = matchCandidateIdx -
                                MAX_(matchCandidateIdx - (U32)backLength, lowestMatchIndex);
                            currentSegmentLength = backLength + forwardPatternLength;

                            if ((currentSegmentLength >= srcPatternLength)
                                && (forwardPatternLength <= srcPatternLength)) {
                                U32 const newMatchIndex =
                                    matchCandidateIdx + (U32)forwardPatternLength - (U32)srcPatternLength;
                                if (LZ4HC_protectDictEnd(prefixIdx, newMatchIndex))
                                    matchIndex = newMatchIndex;
                                else
                                    matchIndex = prefixIdx;
                            } else {
                                U32 const newMatchIndex = matchCandidateIdx - (U32)backLength;
                                if (!LZ4HC_protectDictEnd(prefixIdx, newMatchIndex)) {
                                    matchIndex = prefixIdx;
                                } else {
                                    matchIndex = newMatchIndex;
                                    if (lookBackLength == 0) {
                                        size_t const maxML = MIN_(currentSegmentLength, srcPatternLength);
                                        if ((size_t)longest < maxML) {
                                            if ((size_t)(ip - prefixPtr) + prefixIdx - matchIndex > LZ4_DISTANCE_MAX)
                                                break;
                                            longest = (int)maxML;
                                            *matchpos = prefixPtr - prefixIdx + matchIndex;
                                            *startpos = ip;
                                        }
                                        {   U32 const distToNextPattern = DELTANEXTU16(chainTable, matchIndex);
                                            if (distToNextPattern > matchIndex) break;
                                            matchIndex -= distToNextPattern;
                                        }
                                    }
                                }
                            }
                        }
                        continue;
                    }
                }
            }
        }

        /* follow the current chain */
        matchIndex -= DELTANEXTU16(chainTable, matchIndex + matchChainPos);
    }

    if (dict == usingDictCtxHc
        && nbAttempts > 0
        && ipIndex - lowestMatchIndex < LZ4_DISTANCE_MAX) {
        size_t const dictEndOffset =
            (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
        U32 dictMatchIndex = dictCtx->hashTable[hc_hashPtr(ip)];
        matchIndex = dictMatchIndex + lowestMatchIndex - (U32)dictEndOffset;
        if (dictMatchIndex > 0) while (ipIndex - matchIndex <= LZ4_DISTANCE_MAX && nbAttempts--) {
            const BYTE *const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + dictMatchIndex;

            if (hrd32(matchPtr) == pattern) {
                int mlt;
                int back = 0;
                const BYTE *vLimit = ip + (dictEndOffset - dictMatchIndex);
                if (vLimit > iHighLimit) vLimit = iHighLimit;
                mlt = (int)hc_count(ip + MINMATCH, matchPtr + MINMATCH, vLimit) + MINMATCH;
                back = lookBackLength ? LZ4HC_countBack(ip, matchPtr, iLowLimit, dictCtx->prefixStart) : 0;
                mlt -= back;
                if (mlt > longest) {
                    longest = mlt;
                    *matchpos = prefixPtr - prefixIdx + matchIndex + back;
                    *startpos = ip + back;
                }
            }
            {   U32 const nextOffset = DELTANEXTU16(dictCtx->chainTable, dictMatchIndex);
                dictMatchIndex -= nextOffset;
                matchIndex -= nextOffset;
                if (nextOffset == 0) break;
            }
        }
    }

    return longest;
}

FORCE_INLINE int
LZ4HC_InsertAndFindBestMatch(lz4hc_ctx_t *const hc4,
                            const BYTE *const ip, const BYTE *const iLimit,
                            const BYTE **matchpos,
                            const int maxNbAttempts,
                            const int patternAnalysis,
                            const dictctx_e dict)
{
    const BYTE *uselessPtr = ip;
    return LZ4HC_InsertAndGetWiderMatch(hc4, ip, ip, iLimit, MINMATCH - 1, matchpos, &uselessPtr,
                                        maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
}

/* ------------------------------------------------------------------ */
/* sequence encoding                                                   */
/* ------------------------------------------------------------------ */

#define UPDATABLE(ip, op, anchor) &ip, &op, &anchor

FORCE_INLINE int LZ4HC_encodeSequence(
        const BYTE **_ip,
        BYTE **_op,
        const BYTE **_anchor,
        int matchLength,
        const BYTE *const match,
        limit_e limit,
        BYTE *oend)
{
    size_t length;
    BYTE *const token = (*_op)++;

    /* literal length */
    length = (size_t)(*_ip - *_anchor);
    if ((limit) && ((*_op + (length / 255) + length + (2 + 1 + LASTLITERALS)) > oend))
        return 1;
    if (length >= RUN_MASK) {
        size_t len = length - RUN_MASK;
        *token = (BYTE)(RUN_MASK << ML_BITS);
        for (; len >= 255; len -= 255) *(*_op)++ = 255;
        *(*_op)++ = (BYTE)len;
    } else {
        *token = (BYTE)(length << ML_BITS);
    }

    /* literals */
    hc_wildCopy8(*_op, *_anchor, (*_op) + length);
    *_op += length;

    /* offset */
    hwrLE16(*_op, (U16)(*_ip - match));
    *_op += 2;

    /* match length */
    length = (size_t)matchLength - MINMATCH;
    if ((limit) && (*_op + (length / 255) + (1 + LASTLITERALS) > oend))
        return 1;
    if (length >= ML_MASK) {
        *token += (BYTE)ML_MASK;
        length -= ML_MASK;
        for (; length >= 510; length -= 510) { *(*_op)++ = 255; *(*_op)++ = 255; }
        if (length >= 255) { length -= 255; *(*_op)++ = 255; }
        *(*_op)++ = (BYTE)length;
    } else {
        *token += (BYTE)length;
    }

    *_ip += matchLength;
    *_anchor = *_ip;
    return 0;
}

/* ------------------------------------------------------------------ */
/* hash chain parser (levels 3..9)                                     */
/* ------------------------------------------------------------------ */

FORCE_INLINE int LZ4HC_compress_hashChain(
        lz4hc_ctx_t *const ctx,
        const char *const source,
        char *const dest,
        int *srcSizePtr,
        int const maxOutputSize,
        int maxNbAttempts,
        const limit_e limit,
        const dictctx_e dict)
{
    const int inputSize = *srcSizePtr;
    const int patternAnalysis = (maxNbAttempts > 128);   /* levels 9+ */

    const BYTE *ip = (const BYTE *)source;
    const BYTE *anchor = ip;
    const BYTE *const iend = ip + inputSize;
    const BYTE *const mflimit = iend - MFLIMIT;
    const BYTE *const matchlimit = (iend - LASTLITERALS);

    BYTE *op = (BYTE *)dest;
    BYTE *oend = op + maxOutputSize;

    int ml0, ml, ml2, ml3;
    const BYTE *start0;
    const BYTE *ref0;
    const BYTE *ref = NULL;
    const BYTE *start2 = NULL;
    const BYTE *ref2 = NULL;
    const BYTE *start3 = NULL;
    const BYTE *ref3 = NULL;

    *srcSizePtr = 0;
    if (limit == fillOutput) oend -= LASTLITERALS;
    if (inputSize < LZ4_MIN_LENGTH) goto _last_literals;

    while (ip <= mflimit) {
        ml = LZ4HC_InsertAndFindBestMatch(ctx, ip, matchlimit, &ref, maxNbAttempts, patternAnalysis, dict);
        if (ml < MINMATCH) { ip++; continue; }

        start0 = ip; ref0 = ref; ml0 = ml;

_Search2:
        if (ip + ml <= mflimit) {
            ml2 = LZ4HC_InsertAndGetWiderMatch(ctx,
                        ip + ml - 2, ip + 0, matchlimit, ml, &ref2, &start2,
                        maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
        } else {
            ml2 = ml;
        }

        if (ml2 == ml) {   /* no better match: encode ML1 */
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
            continue;
        }

        if (start0 < ip) {   /* first match was skipped at least once */
            if (start2 < ip + ml0) {   /* squeezing ML1 between ML0 and ML2 */
                ip = start0; ref = ref0; ml = ml0;
            }
        }

        if ((start2 - ip) < 3) {   /* first match too small: removed */
            ml = ml2;
            ip = start2;
            ref = ref2;
            goto _Search2;
        }

_Search3:
        if ((start2 - ip) < OPTIMAL_ML) {
            int correction;
            int new_ml = ml;
            if (new_ml > OPTIMAL_ML) new_ml = OPTIMAL_ML;
            if (ip + new_ml > start2 + ml2 - MINMATCH)
                new_ml = (int)(start2 - ip) + ml2 - MINMATCH;
            correction = new_ml - (int)(start2 - ip);
            if (correction > 0) {
                start2 += correction;
                ref2 += correction;
                ml2 -= correction;
            }
        }

        if (start2 + ml2 <= mflimit) {
            ml3 = LZ4HC_InsertAndGetWiderMatch(ctx,
                        start2 + ml2 - 3, start2, matchlimit, ml2, &ref3, &start3,
                        maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
        } else {
            ml3 = ml2;
        }

        if (ml3 == ml2) {   /* no better match: encode ML1 and ML2 */
            if (start2 < ip + ml) ml = (int)(start2 - ip);
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
            ip = start2;
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml2, ref2, limit, oend)) {
                ml = ml2;
                ref = ref2;
                goto _dest_overflow;
            }
            continue;
        }

        if (start3 < ip + ml + 3) {   /* not enough space for match 2: remove it */
            if (start3 >= (ip + ml)) {   /* can write Seq1 immediately */
                if (start2 < ip + ml) {
                    int correction = (int)(ip + ml - start2);
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                    if (ml2 < MINMATCH) {
                        start2 = start3;
                        ref2 = ref3;
                        ml2 = ml3;
                    }
                }

                if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
                ip = start3;
                ref = ref3;
                ml = ml3;

                start0 = start2;
                ref0 = ref2;
                ml0 = ml2;
                goto _Search2;
            }

            start2 = start3;
            ref2 = ref3;
            ml2 = ml3;
            goto _Search3;
        }

        /* three ascending matches: write the first one */
        if (start2 < ip + ml) {
            if ((start2 - ip) < OPTIMAL_ML) {
                int correction;
                if (ml > OPTIMAL_ML) ml = OPTIMAL_ML;
                if (ip + ml > start2 + ml2 - MINMATCH)
                    ml = (int)(start2 - ip) + ml2 - MINMATCH;
                correction = ml - (int)(start2 - ip);
                if (correction > 0) {
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                }
            } else {
                ml = (int)(start2 - ip);
            }
        }
        if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;

        ip = start2;
        ref = ref2;
        ml = ml2;

        start2 = start3;
        ref2 = ref3;
        ml2 = ml3;

        goto _Search3;
    }

_last_literals:
    {   size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit == fillOutput) oend += LASTLITERALS;
        if (limit && (op + totalSize > oend)) {
            if (limit == limitedOutput) return 0;
            lastRunSize = (size_t)(oend - op) - 1;
            llAdd = (lastRunSize + 256 - RUN_MASK) / 256;
            lastRunSize -= llAdd;
        }
        ip = anchor + lastRunSize;

        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }

    *srcSizePtr = (int)(((const char *)ip) - source);
    return (int)(((char *)op) - dest);

_dest_overflow:
    if (limit == fillOutput) {
        /* not used by the frame layer */
        return 0;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* optimal parser (levels 10..12)                                      */
/* ------------------------------------------------------------------ */

typedef struct { int price; int off; int mlen; int litlen; } lz4hc_optimal_t;

static int LZ4HC_literalsPrice(int const litlen)
{
    int price = litlen;
    if (litlen >= (int)RUN_MASK) price += 1 + ((litlen - (int)RUN_MASK) / 255);
    return price;
}

static int LZ4HC_sequencePrice(int litlen, int mlen)
{
    int price = 1 + 2;   /* token + 16-bit offset */
    price += LZ4HC_literalsPrice(litlen);
    if (mlen >= (int)(ML_MASK + MINMATCH))
        price += 1 + ((mlen - (int)(ML_MASK + MINMATCH)) / 255);
    return price;
}

typedef struct { int off; int len; } lz4hc_match_t;

FORCE_INLINE lz4hc_match_t
LZ4HC_FindLongerMatch(lz4hc_ctx_t *const ctx,
                      const BYTE *ip, const BYTE *const iHighLimit,
                      int minLen, int nbSearches,
                      const dictctx_e dict,
                      const hcfavor_e favorDecSpeed)
{
    lz4hc_match_t match = { 0, 0 };
    const BYTE *matchPtr = NULL;
    int matchLength = LZ4HC_InsertAndGetWiderMatch(ctx, ip, ip, iHighLimit, minLen,
                                                   &matchPtr, &ip, nbSearches,
                                                   1 /*patternAnalysis*/, 1 /*chainSwap*/,
                                                   dict, favorDecSpeed);
    if (matchLength <= minLen) return match;
    if (favorDecSpeed) {
        if ((matchLength > 18) & (matchLength <= 36)) matchLength = 18;
    }
    match.len = matchLength;
    match.off = (int)(ip - matchPtr);
    return match;
}

#define TRAILING_LITERALS 3

static lz4hc_optimal_t g_opt[LZ4_OPT_NUM + TRAILING_LITERALS];

FORCE_INLINE int LZ4HC_compress_optimal(
        lz4hc_ctx_t *ctx,
        const char *const source,
        char *dst,
        int *srcSizePtr,
        int dstCapacity,
        int const nbSearches,
        size_t sufficient_len,
        const limit_e limit,
        int const fullUpdate,
        const dictctx_e dict,
        const hcfavor_e favorDecSpeed)
{
    lz4hc_optimal_t *const opt = g_opt;

    const BYTE *ip = (const BYTE *)source;
    const BYTE *anchor = ip;
    const BYTE *const iend = ip + *srcSizePtr;
    const BYTE *const mflimit = iend - MFLIMIT;
    const BYTE *const matchlimit = iend - LASTLITERALS;
    BYTE *op = (BYTE *)dst;
    BYTE *oend = op + dstCapacity;

    *srcSizePtr = 0;
    if (limit == fillOutput) oend -= LASTLITERALS;
    if (sufficient_len >= LZ4_OPT_NUM) sufficient_len = LZ4_OPT_NUM - 1;
    if ((int)(iend - ip) < LZ4_MIN_LENGTH) goto _last_literals;

    while (ip <= mflimit) {
        int const llen = (int)(ip - anchor);
        int best_mlen, best_off;
        int cur, last_match_pos = 0;

        lz4hc_match_t const firstMatch =
            LZ4HC_FindLongerMatch(ctx, ip, matchlimit, MINMATCH - 1, nbSearches, dict, favorDecSpeed);
        if (firstMatch.len == 0) { ip++; continue; }

        if ((size_t)firstMatch.len > sufficient_len) {
            int const firstML = firstMatch.len;
            const BYTE *const matchPos = ip - firstMatch.off;
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), firstML, matchPos, limit, oend))
                goto _dest_overflow;
            continue;
        }

        /* prices for the first positions (literals) */
        {   int rPos;
            for (rPos = 0; rPos < MINMATCH; rPos++) {
                int const cost = LZ4HC_literalsPrice(llen + rPos);
                opt[rPos].mlen = 1;
                opt[rPos].off = 0;
                opt[rPos].litlen = llen + rPos;
                opt[rPos].price = cost;
            }
        }
        /* prices using the initial match */
        {   int mlen = MINMATCH;
            int const matchML = firstMatch.len;
            int const offset = firstMatch.off;
            for (; mlen <= matchML; mlen++) {
                int const cost = LZ4HC_sequencePrice(llen, mlen);
                opt[mlen].mlen = mlen;
                opt[mlen].off = offset;
                opt[mlen].litlen = llen;
                opt[mlen].price = cost;
            }
        }
        last_match_pos = firstMatch.len;
        {   int addLit;
            for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                opt[last_match_pos + addLit].mlen = 1;
                opt[last_match_pos + addLit].off = 0;
                opt[last_match_pos + addLit].litlen = addLit;
                opt[last_match_pos + addLit].price =
                    opt[last_match_pos].price + LZ4HC_literalsPrice(addLit);
            }
        }

        for (cur = 1; cur < last_match_pos; cur++) {
            const BYTE *const curPtr = ip + cur;
            lz4hc_match_t newMatch;

            if (curPtr > mflimit) break;
            if (fullUpdate) {
                if ((opt[cur + 1].price <= opt[cur].price)
                    && (opt[cur + MINMATCH].price < opt[cur].price + 3))
                    continue;
            } else {
                if (opt[cur + 1].price <= opt[cur].price) continue;
            }

            newMatch = LZ4HC_FindLongerMatch(ctx, curPtr, matchlimit, MINMATCH - 1,
                                             nbSearches, dict, favorDecSpeed);
            if (!newMatch.len) continue;

            if (((size_t)newMatch.len > sufficient_len)
                || (newMatch.len + cur >= LZ4_OPT_NUM)) {
                best_mlen = newMatch.len;
                best_off = newMatch.off;
                last_match_pos = cur + 1;
                goto encode;
            }

            /* before match: set price with literals at the beginning */
            {   int const baseLitlen = opt[cur].litlen;
                int litlen;
                for (litlen = 1; litlen < MINMATCH; litlen++) {
                    int const price = opt[cur].price - LZ4HC_literalsPrice(baseLitlen)
                                    + LZ4HC_literalsPrice(baseLitlen + litlen);
                    int const pos = cur + litlen;
                    if (price < opt[pos].price) {
                        opt[pos].mlen = 1;
                        opt[pos].off = 0;
                        opt[pos].litlen = baseLitlen + litlen;
                        opt[pos].price = price;
                    }
                }
            }

            /* prices using the match at position `cur` */
            {   int const matchML = newMatch.len;
                int ml = MINMATCH;
                for (; ml <= matchML; ml++) {
                    int const pos = cur + ml;
                    int const offset = newMatch.off;
                    int price;
                    int ll;
                    if (opt[cur].mlen == 1) {
                        ll = opt[cur].litlen;
                        price = ((cur > ll) ? opt[cur - ll].price : 0)
                              + LZ4HC_sequencePrice(ll, ml);
                    } else {
                        ll = 0;
                        price = opt[cur].price + LZ4HC_sequencePrice(0, ml);
                    }

                    if (pos > last_match_pos + TRAILING_LITERALS
                        || price <= opt[pos].price - (int)favorDecSpeed) {
                        if (ml == matchML && last_match_pos < pos) last_match_pos = pos;
                        opt[pos].mlen = ml;
                        opt[pos].off = offset;
                        opt[pos].litlen = ll;
                        opt[pos].price = price;
                    }
                }
            }
            /* complete following positions with literals */
            {   int addLit;
                for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                    opt[last_match_pos + addLit].mlen = 1;
                    opt[last_match_pos + addLit].off = 0;
                    opt[last_match_pos + addLit].litlen = addLit;
                    opt[last_match_pos + addLit].price =
                        opt[last_match_pos].price + LZ4HC_literalsPrice(addLit);
                }
            }
        }

        best_mlen = opt[last_match_pos].mlen;
        best_off = opt[last_match_pos].off;
        cur = last_match_pos - best_mlen;

encode:
        {   int candidate_pos = cur;
            int selected_matchLength = best_mlen;
            int selected_offset = best_off;
            while (1) {
                int const next_matchLength = opt[candidate_pos].mlen;
                int const next_offset = opt[candidate_pos].off;
                opt[candidate_pos].mlen = selected_matchLength;
                opt[candidate_pos].off = selected_offset;
                selected_matchLength = next_matchLength;
                selected_offset = next_offset;
                if (next_matchLength > candidate_pos) break;
                candidate_pos -= next_matchLength;
            }
        }

        {   int rPos = 0;
            while (rPos < last_match_pos) {
                int const ml = opt[rPos].mlen;
                int const offset = opt[rPos].off;
                if (ml == 1) { ip++; rPos++; continue; }
                rPos += ml;
                if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ip - offset, limit, oend))
                    goto _dest_overflow;
            }
        }
    }

_last_literals:
    {   size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit == fillOutput) oend += LASTLITERALS;
        if (limit && (op + totalSize > oend)) {
            if (limit == limitedOutput) return 0;
            lastRunSize = (size_t)(oend - op) - 1;
            llAdd = (lastRunSize + 256 - RUN_MASK) / 256;
            lastRunSize -= llAdd;
        }
        ip = anchor + lastRunSize;

        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }

    *srcSizePtr = (int)(((const char *)ip) - source);
    return (int)((char *)op - dst);

_dest_overflow:
    return 0;
}

/* ------------------------------------------------------------------ */
/* level dispatch                                                      */
/* ------------------------------------------------------------------ */

typedef enum { strat_hc, strat_opt } hcstrat_e;
typedef struct { hcstrat_e strat; int nbSearches; unsigned targetLength; } cparams_t;

static const cparams_t k_clTable[LZ4HC_CLEVEL_MAX + 1] = {
    { strat_hc,      2,  16 },  /* 0, unused */
    { strat_hc,      2,  16 },  /* 1, unused */
    { strat_hc,      2,  16 },  /* 2 */
    { strat_hc,      4,  16 },  /* 3 */
    { strat_hc,      8,  16 },  /* 4 */
    { strat_hc,     16,  16 },  /* 5 */
    { strat_hc,     32,  16 },  /* 6 */
    { strat_hc,     64,  16 },  /* 7 */
    { strat_hc,    128,  16 },  /* 8 */
    { strat_hc,    256,  16 },  /* 9 */
    { strat_opt,    96,  64 },  /* 10 */
    { strat_opt,   512, 128 },  /* 11 */
    { strat_opt, 16384, LZ4_OPT_NUM }, /* 12 */
};

static int LZ4HC_compress_generic_internal(
        lz4hc_ctx_t *const ctx,
        const char *const src,
        char *const dst,
        int *const srcSizePtr,
        int const dstCapacity,
        int cLevel,
        const limit_e limit,
        const dictctx_e dict)
{
    if (limit == fillOutput && dstCapacity < 1) return 0;
    if ((unsigned)*srcSizePtr > (unsigned)LZ4_MAX_INPUT_SIZE) return 0;

    ctx->end += *srcSizePtr;
    if (cLevel < 1) cLevel = LZ4HC_CLEVEL_DEFAULT;
    cLevel = MIN_(LZ4HC_CLEVEL_MAX, cLevel);
    {   cparams_t const cParam = k_clTable[cLevel];
        hcfavor_e const favor = ctx->favorDecSpeed ? favorDecompressionSpeed : favorCompressionRatio;
        int result;

        if (cParam.strat == strat_hc) {
            result = LZ4HC_compress_hashChain(ctx, src, dst, srcSizePtr, dstCapacity,
                                              cParam.nbSearches, limit, dict);
        } else {
            result = LZ4HC_compress_optimal(ctx, src, dst, srcSizePtr, dstCapacity,
                                            cParam.nbSearches, cParam.targetLength, limit,
                                            cLevel == LZ4HC_CLEVEL_MAX, dict, favor);
        }
        if (result <= 0) ctx->dirty = 1;
        return result;
    }
}

static void LZ4HC_setExternalDict(lz4hc_ctx_t *ctxPtr, const BYTE *newBlock)
{
    if (ctxPtr->end >= ctxPtr->prefixStart + 4)
        LZ4HC_Insert(ctxPtr, ctxPtr->end - 3);

    ctxPtr->lowLimit = ctxPtr->dictLimit;
    ctxPtr->dictStart = ctxPtr->prefixStart;
    ctxPtr->dictLimit += (U32)(ctxPtr->end - ctxPtr->prefixStart);
    ctxPtr->prefixStart = newBlock;
    ctxPtr->end = newBlock;
    ctxPtr->nextToUpdate = ctxPtr->dictLimit;

    ctxPtr->dictCtx = NULL;
}

static int LZ4HC_compress_generic_noDictCtx(
        lz4hc_ctx_t *const ctx, const char *const src, char *const dst,
        int *const srcSizePtr, int const dstCapacity, int cLevel, limit_e limit)
{
    return LZ4HC_compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity,
                                           cLevel, limit, noDictCtx);
}

static int LZ4HC_compress_generic_dictCtx(
        lz4hc_ctx_t *const ctx, const char *const src, char *const dst,
        int *const srcSizePtr, int const dstCapacity, int cLevel, limit_e limit)
{
    const size_t position = (size_t)(ctx->end - ctx->prefixStart) + (ctx->dictLimit - ctx->lowLimit);
    if (position >= 64 * KB_) {
        ctx->dictCtx = NULL;
        return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    } else if (position == 0 && *srcSizePtr > 4 * KB_) {
        memcpy(ctx, ctx->dictCtx, sizeof(lz4hc_ctx_t));
        LZ4HC_setExternalDict(ctx, (const BYTE *)src);
        ctx->compressionLevel = (short)cLevel;
        return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    } else {
        return LZ4HC_compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity,
                                               cLevel, limit, usingDictCtxHc);
    }
}

static int LZ4HC_compress_generic(
        lz4hc_ctx_t *const ctx, const char *const src, char *const dst,
        int *const srcSizePtr, int const dstCapacity, int cLevel, limit_e limit)
{
    if (ctx->dictCtx == NULL)
        return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    return LZ4HC_compress_generic_dictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
}

/* ------------------------------------------------------------------ */
/* public API                                                          */
/* ------------------------------------------------------------------ */

void LZ4_setCompressionLevel(lz4hc_ctx_t *s, int level)
{
    if (level < 1) level = LZ4HC_CLEVEL_DEFAULT;
    if (level > LZ4HC_CLEVEL_MAX) level = LZ4HC_CLEVEL_MAX;
    s->compressionLevel = (short)level;
}

void LZ4_favorDecompressionSpeed(lz4hc_ctx_t *s, int favor)
{
    s->favorDecSpeed = (signed char)(favor != 0);
}

void LZ4_initStreamHC(lz4hc_ctx_t *s)
{
    memset(s, 0, sizeof(*s));
    LZ4_setCompressionLevel(s, LZ4HC_CLEVEL_DEFAULT);
}

void LZ4_resetStreamHC_fast(lz4hc_ctx_t *s, int level)
{
    if (s->dirty) {
        signed char const favor = s->favorDecSpeed;
        LZ4_initStreamHC(s);
        s->favorDecSpeed = favor;
    } else {
        s->dictLimit += (U32)(s->end - s->prefixStart);
        s->prefixStart = NULL;
        s->end = NULL;
        s->dictStart = NULL;
    }
    LZ4_setCompressionLevel(s, level);
}

int LZ4_compress_HC_extStateHC_fastReset(lz4hc_ctx_t *s, const char *src, char *dst,
                                         int srcSize, int dstCapacity, int level)
{
    LZ4_resetStreamHC_fast(s, level);
    LZ4HC_init_internal(s, (const BYTE *)src);
    if (dstCapacity < LZ4_compressBound(srcSize))
        return LZ4HC_compress_generic(s, src, dst, &srcSize, dstCapacity, level, limitedOutput);
    return LZ4HC_compress_generic(s, src, dst, &srcSize, dstCapacity, level, notLimited);
}

int LZ4_loadDictHC(lz4hc_ctx_t *s, const char *dictionary, int dictSize)
{
    const BYTE *p = (const BYTE *)dictionary;
    if (dictSize > 64 * KB_) {
        p += dictSize - 64 * KB_;
        dictSize = 64 * KB_;
    }
    /* need a full reset so that indexes remain valid */
    {   short const level = s->compressionLevel;
        signed char const favor = s->favorDecSpeed;
        LZ4_initStreamHC(s);
        s->compressionLevel = level;
        s->favorDecSpeed = favor;
    }
    LZ4HC_init_internal(s, p);
    s->end = p + dictSize;
    if (dictSize >= 4) LZ4HC_Insert(s, s->end - 3);
    return dictSize;
}

void LZ4_attach_HC_dictionary(lz4hc_ctx_t *working, const lz4hc_ctx_t *dictCtx)
{
    working->dictCtx = dictCtx;
}

static void LZ4HC_renormDictT(lz4hc_ctx_t *ctxPtr, int nextSize)
{
    if (ctxPtr->end - ctxPtr->prefixStart + nextSize > (ptrdiff_t)(2u << 30)) {
        size_t const dictSize = (size_t)(ctxPtr->end - ctxPtr->prefixStart);
        const BYTE *dictBegin = ctxPtr->prefixStart;
        int i;
        LZ4HC_clearTables(ctxPtr);
        ctxPtr->dictLimit = 0;
        ctxPtr->lowLimit = 0;
        ctxPtr->nextToUpdate = 0;
        ctxPtr->prefixStart = dictBegin;
        ctxPtr->end = dictBegin + dictSize;
        ctxPtr->dictStart = dictBegin;
        (void)i;
    }
}

int LZ4_compress_HC_continue(lz4hc_ctx_t *ctxPtr, const char *src, char *dst,
                             int srcSize, int dstCapacity)
{
    limit_e const limit = (dstCapacity < LZ4_compressBound(srcSize)) ? limitedOutput : notLimited;

    LZ4HC_renormDictT(ctxPtr, srcSize);
    if (ctxPtr->dirty) return 0;
    if (ctxPtr->prefixStart == NULL) LZ4HC_init_internal(ctxPtr, (const BYTE *)src);

    /* check overlapping input / dictionary space */
    {   const char *sourceEnd = src + srcSize;
        const char *const dictBegin = (const char *)ctxPtr->dictStart;
        const char *const dictEnd = (const char *)ctxPtr->dictStart + (ctxPtr->dictLimit - ctxPtr->lowLimit);
        if ((sourceEnd > dictBegin) && ((const char *)src < dictEnd)) {
            if (sourceEnd > dictEnd) sourceEnd = dictEnd;
            ctxPtr->lowLimit += (U32)(sourceEnd - ctxPtr->dictStart);
            ctxPtr->dictStart += (U32)(sourceEnd - (const char *)ctxPtr->dictStart);
