    return LZ4HC_compress_generic(ctxPtr, src, dst, &srcSize, dstCapacity,
                                  ctxPtr->compressionLevel, limit);
}

int LZ4_saveDictHC(lz4hc_ctx_t *ctxPtr, char *safeBuffer, int dictSize)
{
