        ctxPtr->dictStart = ctxPtr->prefixStart;
        if (ctxPtr->nextToUpdate < ctxPtr->dictLimit)
            ctxPtr->nextToUpdate = ctxPtr->dictLimit;
    }
    return dictSize;
}

