/*
 * lz4hc.c - LZ4 high compression variant
 *
 * Independent implementation of the LZ4 "HC" match finder and parsers.
 * BSD 2-Clause License
 */
#include "lz4hc.h"
#include "lz4blk.h"
#include <string.h>

#ifdef __GNUC__
#  define FORCE_INLINE static inline __attribute__((always_inline))
#  define LIKELY(x)    __builtin_expect(!!(x), 1)
#  define UNLIKELY(x)  __builtin_expect(!!(x), 0)
#else
#  define FORCE_INLINE static inline
#  define LIKELY(x)    (x)
#  define UNLIKELY(x)  (x)
#endif

typedef unsigned char BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;
typedef size_t   reg_t;

#define MINMATCH 4
#define WILDCOPYLENGTH 8
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_MIN_LENGTH (MFLIMIT + 1)
#define ML_BITS  4
#define ML_MASK  ((1u << ML_BITS) - 1)
#define RUN_BITS (8 - ML_BITS)
#define RUN_MASK ((1u << RUN_BITS) - 1)
#define KB_ (1 << 10)
#define LZ4_DISTANCE_MAX 65535
#define OPTIMAL_ML ((int)((ML_MASK - 1) + MINMATCH))
#define LZ4_OPT_NUM (1 << 12)

#define MIN_(a,b) ((a) < (b) ? (a) : (b))
#define MAX_(a,b) ((a) > (b) ? (a) : (b))

typedef enum { notLimited = 0, limitedOutput = 1, fillOutput = 2 } limit_e;
typedef enum { noDictCtx = 0, usingDictCtxHc } dictctx_e;
typedef enum { favorCompressionRatio = 0, favorDecompressionSpeed } hcfavor_e;
typedef enum { rep_untested, rep_not, rep_confirmed } repeat_e;

/* ------------------------------------------------------------------ */
/* unaligned access                                                    */
/* ------------------------------------------------------------------ */

typedef union { U16 u16; U32 u32; reg_t uArch; } __attribute__((packed)) unalign2_t;
static U16   hrd16(const void *p) { return ((const unalign2_t *)p)->u16; }
static U32   hrd32(const void *p) { return ((const unalign2_t *)p)->u32; }
static reg_t hrdArch(const void *p) { return ((const unalign2_t *)p)->uArch; }
static void  hwr16(void *p, U16 v) { ((unalign2_t *)p)->u16 = v; }

static int hc_isLE(void)
{
    const union { U32 u; BYTE c[4]; } one = { 1 };
    return one.c[0];
}

static void hwrLE16(void *p, U16 v)
{
    if (hc_isLE()) { hwr16(p, v); return; }
    { BYTE *b = (BYTE *)p; b[0] = (BYTE)v; b[1] = (BYTE)(v >> 8); }
}

static unsigned hc_nbCommonBytes(reg_t val)
{
    if (hc_isLE()) {
        if (sizeof(reg_t) == 8) return (unsigned)__builtin_ctzll((U64)val) >> 3;
        return (unsigned)__builtin_ctz((U32)val) >> 3;
    } else {
        if (sizeof(reg_t) == 8) return (unsigned)__builtin_clzll((U64)val) >> 3;
        return (unsigned)__builtin_clz((U32)val) >> 3;
