static unsigned hc_count(const BYTE *pIn, const BYTE *pMatch, const BYTE *pInLimit)
{
    const BYTE *const pStart = pIn;

    if (LIKELY(pIn < pInLimit - (sizeof(reg_t) - 1))) {
        reg_t const diff = hrdArch(pMatch) ^ hrdArch(pIn);
        if (!diff) { pIn += sizeof(reg_t); pMatch += sizeof(reg_t); }
        else return hc_nbCommonBytes(diff);
    }
    while (LIKELY(pIn < pInLimit - (sizeof(reg_t) - 1))) {
        reg_t const diff = hrdArch(pMatch) ^ hrdArch(pIn);
        if (!diff) { pIn += sizeof(reg_t); pMatch += sizeof(reg_t); continue; }
        pIn += hc_nbCommonBytes(diff);
        return (unsigned)(pIn - pStart);
    }
    if ((sizeof(reg_t) == 8) && (pIn < (pInLimit - 3)) && (hrd32(pMatch) == hrd32(pIn))) {
        pIn += 4; pMatch += 4;
    }
    if ((pIn < (pInLimit - 1)) && (hrd16(pMatch) == hrd16(pIn))) { pIn += 2; pMatch += 2; }
