/* ------------------------------------------------------------------ */
/* chain table                                                         */
/* ------------------------------------------------------------------ */

#define HASH_FUNCTION(i) (((i) * 2654435761u) >> ((MINMATCH * 8) - LZ4HC_HASH_LOG))
#define DELTANEXTU16(table, pos) table[(U16)(pos)]

