}

/* count matching bytes backwards; returns a negative number */
static int LZ4HC_countBack(const BYTE *const ip, const BYTE *const match,
                           const BYTE *const iMin, const BYTE *const mMin)
{
    int back = 0;
    int const min = (int)MAX_(iMin - ip, mMin - match);
    while ((back > min) && (ip[back - 1] == match[back - 1])) back--;
    return back;
}

static unsigned LZ4HC_countPattern(const BYTE *ip, const BYTE *const iEnd, U32 const pattern32)
{
    const BYTE *const iStart = ip;
    reg_t const pattern = (sizeof(pattern) == 8) ?
        (reg_t)pattern32 + (((reg_t)pattern32) << (sizeof(pattern) * 4)) : (reg_t)pattern32;

    while (LIKELY(ip < iEnd - (sizeof(pattern) - 1))) {
        reg_t const diff = hrdArch(ip) ^ pattern;
        if (!diff) { ip += sizeof(pattern); continue; }
        ip += hc_nbCommonBytes(diff);
