}

/* rotate a 4-byte pattern by `rotate` bytes */
static U32 LZ4HC_rotatePattern(size_t rotate, U32 pattern)
{
    size_t const bitsToRotate = (rotate & (sizeof(pattern) - 1)) << 3;
    if (bitsToRotate == 0) return pattern;
    return ((pattern) >> bitsToRotate) | ((pattern) << (32 - bitsToRotate));
