    return longest;
}

FORCE_INLINE int
LZ4HC_InsertAndFindBestMatch(lz4hc_ctx_t *const hc4,
                            const BYTE *const ip, const BYTE *const iLimit,
                            const BYTE **matchpos,
                            const int maxNbAttempts,
                            const int patternAnalysis,
                            const dictctx_e dict)
{
    const BYTE *uselessPtr = ip;
    return LZ4HC_InsertAndGetWiderMatch(hc4, ip, ip, iLimit, MINMATCH - 1, matchpos, &uselessPtr,
                                        maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
}

/* ------------------------------------------------------------------ */
/* sequence encoding                                                   */
/* ------------------------------------------------------------------ */

#define UPDATABLE(ip, op, anchor) &ip, &op, &anchor

FORCE_INLINE int LZ4HC_encodeSequence(
        const BYTE **_ip,
        BYTE **_op,
        const BYTE **_anchor,
        int matchLength,
        const BYTE *const match,
        limit_e limit,
        BYTE *oend)
{
    size_t length;
    BYTE *const token = (*_op)++;

    /* literal length */
    length = (size_t)(*_ip - *_anchor);
    if ((limit) && ((*_op + (length / 255) + length + (2 + 1 + LASTLITERALS)) > oend))
        return 1;
    if (length >= RUN_MASK) {
        size_t len = length - RUN_MASK;
        *token = (BYTE)(RUN_MASK << ML_BITS);
        for (; len >= 255; len -= 255) *(*_op)++ = 255;
        *(*_op)++ = (BYTE)len;
    } else {
        *token = (BYTE)(length << ML_BITS);
    }

    /* literals */
    hc_wildCopy8(*_op, *_anchor, (*_op) + length);
    *_op += length;

    /* offset */
    hwrLE16(*_op, (U16)(*_ip - match));
    *_op += 2;

    /* match length */
    length = (size_t)matchLength - MINMATCH;
    if ((limit) && (*_op + (length / 255) + (1 + LASTLITERALS) > oend))
        return 1;
    if (length >= ML_MASK) {
        *token += (BYTE)ML_MASK;
        length -= ML_MASK;
        for (; length >= 510; length -= 510) { *(*_op)++ = 255; *(*_op)++ = 255; }
        if (length >= 255) { length -= 255; *(*_op)++ = 255; }
        *(*_op)++ = (BYTE)length;
    } else {
        *token += (BYTE)length;
    }

    *_ip += matchLength;
    *_anchor = *_ip;
    return 0;
}

/* ------------------------------------------------------------------ */
/* hash chain parser (levels 3..9)                                     */
/* ------------------------------------------------------------------ */

FORCE_INLINE int LZ4HC_compress_hashChain(
        lz4hc_ctx_t *const ctx,
        const char *const source,
        char *const dest,
        int *srcSizePtr,
        int const maxOutputSize,
        int maxNbAttempts,
        const limit_e limit,
        const dictctx_e dict)
{
    const int inputSize = *srcSizePtr;
    const int patternAnalysis = (maxNbAttempts > 128);   /* levels 9+ */

    const BYTE *ip = (const BYTE *)source;
    const BYTE *anchor = ip;
    const BYTE *const iend = ip + inputSize;
    const BYTE *const mflimit = iend - MFLIMIT;
    const BYTE *const matchlimit = (iend - LASTLITERALS);

    BYTE *op = (BYTE *)dest;
    BYTE *oend = op + maxOutputSize;

    int ml0, ml, ml2, ml3;
    const BYTE *start0;
    const BYTE *ref0;
    const BYTE *ref = NULL;
    const BYTE *start2 = NULL;
    const BYTE *ref2 = NULL;
    const BYTE *start3 = NULL;
    const BYTE *ref3 = NULL;

    *srcSizePtr = 0;
    if (limit == fillOutput) oend -= LASTLITERALS;
    if (inputSize < LZ4_MIN_LENGTH) goto _last_literals;

    while (ip <= mflimit) {
        ml = LZ4HC_InsertAndFindBestMatch(ctx, ip, matchlimit, &ref, maxNbAttempts, patternAnalysis, dict);
        if (ml < MINMATCH) { ip++; continue; }

        start0 = ip; ref0 = ref; ml0 = ml;

_Search2:
        if (ip + ml <= mflimit) {
            ml2 = LZ4HC_InsertAndGetWiderMatch(ctx,
                        ip + ml - 2, ip + 0, matchlimit, ml, &ref2, &start2,
                        maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
        } else {
            ml2 = ml;
        }

        if (ml2 == ml) {   /* no better match: encode ML1 */
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
            continue;
        }

        if (start0 < ip) {   /* first match was skipped at least once */
            if (start2 < ip + ml0) {   /* squeezing ML1 between ML0 and ML2 */
                ip = start0; ref = ref0; ml = ml0;
            }
        }

