            ml = ml2;
            ip = start2;
            ref = ref2;
            goto _Search2;
        }

_Search3:
        if ((start2 - ip) < OPTIMAL_ML) {
            int correction;
            int new_ml = ml;
            if (new_ml > OPTIMAL_ML) new_ml = OPTIMAL_ML;
            if (ip + new_ml > start2 + ml2 - MINMATCH)
                new_ml = (int)(start2 - ip) + ml2 - MINMATCH;
            correction = new_ml - (int)(start2 - ip);
            if (correction > 0) {
                start2 += correction;
                ref2 += correction;
                ml2 -= correction;
            }
        }

        if (start2 + ml2 <= mflimit) {
            ml3 = LZ4HC_InsertAndGetWiderMatch(ctx,
                        start2 + ml2 - 3, start2, matchlimit, ml2, &ref3, &start3,
                        maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
        } else {
            ml3 = ml2;
        }

        if (ml3 == ml2) {   /* no better match: encode ML1 and ML2 */
            if (start2 < ip + ml) ml = (int)(start2 - ip);
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
            ip = start2;
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml2, ref2, limit, oend)) {
                ml = ml2;
                ref = ref2;
                goto _dest_overflow;
            }
            continue;
        }

        if (start3 < ip + ml + 3) {   /* not enough space for match 2: remove it */
            if (start3 >= (ip + ml)) {   /* can write Seq1 immediately */
                if (start2 < ip + ml) {
                    int correction = (int)(ip + ml - start2);
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                    if (ml2 < MINMATCH) {
                        start2 = start3;
                        ref2 = ref3;
                        ml2 = ml3;
                    }
                }

                if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;
                ip = start3;
                ref = ref3;
                ml = ml3;

                start0 = start2;
                ref0 = ref2;
                ml0 = ml2;
                goto _Search2;
            }

            start2 = start3;
            ref2 = ref3;
            ml2 = ml3;
            goto _Search3;
        }

        /* three ascending matches: write the first one */
        if (start2 < ip + ml) {
            if ((start2 - ip) < OPTIMAL_ML) {
                int correction;
                if (ml > OPTIMAL_ML) ml = OPTIMAL_ML;
                if (ip + ml > start2 + ml2 - MINMATCH)
                    ml = (int)(start2 - ip) + ml2 - MINMATCH;
                correction = ml - (int)(start2 - ip);
                if (correction > 0) {
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                }
            } else {
                ml = (int)(start2 - ip);
            }
        }
        if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ref, limit, oend)) goto _dest_overflow;

        ip = start2;
        ref = ref2;
        ml = ml2;

        start2 = start3;
        ref2 = ref3;
        ml2 = ml3;

        goto _Search3;
    }

_last_literals:
    {   size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit == fillOutput) oend += LASTLITERALS;
        if (limit && (op + totalSize > oend)) {
            if (limit == limitedOutput) return 0;
            lastRunSize = (size_t)(oend - op) - 1;
            llAdd = (lastRunSize + 256 - RUN_MASK) / 256;
            lastRunSize -= llAdd;
        }
        ip = anchor + lastRunSize;

        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }

    *srcSizePtr = (int)(((const char *)ip) - source);
    return (int)(((char *)op) - dest);

_dest_overflow:
    if (limit == fillOutput) {
        /* not used by the frame layer */
        return 0;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* optimal parser (levels 10..12)                                      */
/* ------------------------------------------------------------------ */

typedef struct { int price; int off; int mlen; int litlen; } lz4hc_optimal_t;

static int LZ4HC_literalsPrice(int const litlen)
{
    int price = litlen;
    if (litlen >= (int)RUN_MASK) price += 1 + ((litlen - (int)RUN_MASK) / 255);
    return price;
}

static int LZ4HC_sequencePrice(int litlen, int mlen)
{
    int price = 1 + 2;   /* token + 16-bit offset */
    price += LZ4HC_literalsPrice(litlen);
    if (mlen >= (int)(ML_MASK + MINMATCH))
        price += 1 + ((mlen - (int)(ML_MASK + MINMATCH)) / 255);
    return price;
}

typedef struct { int off; int len; } lz4hc_match_t;

FORCE_INLINE lz4hc_match_t
LZ4HC_FindLongerMatch(lz4hc_ctx_t *const ctx,
                      const BYTE *ip, const BYTE *const iHighLimit,
                      int minLen, int nbSearches,
                      const dictctx_e dict,
                      const hcfavor_e favorDecSpeed)
{
    lz4hc_match_t match = { 0, 0 };
    const BYTE *matchPtr = NULL;
    int matchLength = LZ4HC_InsertAndGetWiderMatch(ctx, ip, ip, iHighLimit, minLen,
                                                   &matchPtr, &ip, nbSearches,
                                                   1 /*patternAnalysis*/, 1 /*chainSwap*/,
                                                   dict, favorDecSpeed);
    if (matchLength <= minLen) return match;
    if (favorDecSpeed) {
        if ((matchLength > 18) & (matchLength <= 36)) matchLength = 18;
    }
    match.len = matchLength;
    match.off = (int)(ip - matchPtr);
    return match;
}

#define TRAILING_LITERALS 3

static lz4hc_optimal_t g_opt[LZ4_OPT_NUM + TRAILING_LITERALS];

FORCE_INLINE int LZ4HC_compress_optimal(
        lz4hc_ctx_t *ctx,
        const char *const source,
        char *dst,
        int *srcSizePtr,
        int dstCapacity,
        int const nbSearches,
        size_t sufficient_len,
        const limit_e limit,
        int const fullUpdate,
        const dictctx_e dict,
        const hcfavor_e favorDecSpeed)
{
    lz4hc_optimal_t *const opt = g_opt;

    const BYTE *ip = (const BYTE *)source;
    const BYTE *anchor = ip;
    const BYTE *const iend = ip + *srcSizePtr;
    const BYTE *const mflimit = iend - MFLIMIT;
    const BYTE *const matchlimit = iend - LASTLITERALS;
    BYTE *op = (BYTE *)dst;
    BYTE *oend = op + dstCapacity;

    *srcSizePtr = 0;
    if (limit == fillOutput) oend -= LASTLITERALS;
    if (sufficient_len >= LZ4_OPT_NUM) sufficient_len = LZ4_OPT_NUM - 1;
    if ((int)(iend - ip) < LZ4_MIN_LENGTH) goto _last_literals;

    while (ip <= mflimit) {
        int const llen = (int)(ip - anchor);
        int best_mlen, best_off;
        int cur, last_match_pos = 0;

        lz4hc_match_t const firstMatch =
            LZ4HC_FindLongerMatch(ctx, ip, matchlimit, MINMATCH - 1, nbSearches, dict, favorDecSpeed);
        if (firstMatch.len == 0) { ip++; continue; }

        if ((size_t)firstMatch.len > sufficient_len) {
            int const firstML = firstMatch.len;
            const BYTE *const matchPos = ip - firstMatch.off;
            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), firstML, matchPos, limit, oend))
                goto _dest_overflow;
            continue;
        }

        /* prices for the first positions (literals) */
        {   int rPos;
            for (rPos = 0; rPos < MINMATCH; rPos++) {
                int const cost = LZ4HC_literalsPrice(llen + rPos);
                opt[rPos].mlen = 1;
                opt[rPos].off = 0;
                opt[rPos].litlen = llen + rPos;
                opt[rPos].price = cost;
            }
        }
        /* prices using the initial match */
        {   int mlen = MINMATCH;
            int const matchML = firstMatch.len;
            int const offset = firstMatch.off;
            for (; mlen <= matchML; mlen++) {
                int const cost = LZ4HC_sequencePrice(llen, mlen);
                opt[mlen].mlen = mlen;
                opt[mlen].off = offset;
                opt[mlen].litlen = llen;
                opt[mlen].price = cost;
            }
        }
        last_match_pos = firstMatch.len;
        {   int addLit;
            for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                opt[last_match_pos + addLit].mlen = 1;
                opt[last_match_pos + addLit].off = 0;
                opt[last_match_pos + addLit].litlen = addLit;
                opt[last_match_pos + addLit].price =
                    opt[last_match_pos].price + LZ4HC_literalsPrice(addLit);
            }
        }

        for (cur = 1; cur < last_match_pos; cur++) {
            const BYTE *const curPtr = ip + cur;
            lz4hc_match_t newMatch;

            if (curPtr > mflimit) break;
            if (fullUpdate) {
                if ((opt[cur + 1].price <= opt[cur].price)
                    && (opt[cur + MINMATCH].price < opt[cur].price + 3))
                    continue;
            } else {
                if (opt[cur + 1].price <= opt[cur].price) continue;
            }

            newMatch = LZ4HC_FindLongerMatch(ctx, curPtr, matchlimit, MINMATCH - 1,
                                             nbSearches, dict, favorDecSpeed);
            if (!newMatch.len) continue;

            if (((size_t)newMatch.len > sufficient_len)
                || (newMatch.len + cur >= LZ4_OPT_NUM)) {
                best_mlen = newMatch.len;
                best_off = newMatch.off;
                last_match_pos = cur + 1;
                goto encode;
            }

            /* before match: set price with literals at the beginning */
            {   int const baseLitlen = opt[cur].litlen;
                int litlen;
                for (litlen = 1; litlen < MINMATCH; litlen++) {
                    int const price = opt[cur].price - LZ4HC_literalsPrice(baseLitlen)
                                    + LZ4HC_literalsPrice(baseLitlen + litlen);
                    int const pos = cur + litlen;
                    if (price < opt[pos].price) {
                        opt[pos].mlen = 1;
                        opt[pos].off = 0;
                        opt[pos].litlen = baseLitlen + litlen;
                        opt[pos].price = price;
                    }
                }
            }

            /* prices using the match at position `cur` */
            {   int const matchML = newMatch.len;
                int ml = MINMATCH;
                for (; ml <= matchML; ml++) {
                    int const pos = cur + ml;
                    int const offset = newMatch.off;
                    int price;
                    int ll;
                    if (opt[cur].mlen == 1) {
                        ll = opt[cur].litlen;
                        price = ((cur > ll) ? opt[cur - ll].price : 0)
                              + LZ4HC_sequencePrice(ll, ml);
                    } else {
                        ll = 0;
                        price = opt[cur].price + LZ4HC_sequencePrice(0, ml);
                    }

                    if (pos > last_match_pos + TRAILING_LITERALS
                        || price <= opt[pos].price - (int)favorDecSpeed) {
                        if (ml == matchML && last_match_pos < pos) last_match_pos = pos;
                        opt[pos].mlen = ml;
                        opt[pos].off = offset;
                        opt[pos].litlen = ll;
                        opt[pos].price = price;
                    }
                }
            }
            /* complete following positions with literals */
            {   int addLit;
                for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                    opt[last_match_pos + addLit].mlen = 1;
                    opt[last_match_pos + addLit].off = 0;
                    opt[last_match_pos + addLit].litlen = addLit;
                    opt[last_match_pos + addLit].price =
                        opt[last_match_pos].price + LZ4HC_literalsPrice(addLit);
                }
            }
        }

        best_mlen = opt[last_match_pos].mlen;
        best_off = opt[last_match_pos].off;
        cur = last_match_pos - best_mlen;

encode:
        {   int candidate_pos = cur;
            int selected_matchLength = best_mlen;
            int selected_offset = best_off;
            while (1) {
                int const next_matchLength = opt[candidate_pos].mlen;
                int const next_offset = opt[candidate_pos].off;
                opt[candidate_pos].mlen = selected_matchLength;
                opt[candidate_pos].off = selected_offset;
                selected_matchLength = next_matchLength;
                selected_offset = next_offset;
                if (next_matchLength > candidate_pos) break;
                candidate_pos -= next_matchLength;
            }
        }

        {   int rPos = 0;
            while (rPos < last_match_pos) {
                int const ml = opt[rPos].mlen;
                int const offset = opt[rPos].off;
                if (ml == 1) { ip++; rPos++; continue; }
                rPos += ml;
                if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), ml, ip - offset, limit, oend))
                    goto _dest_overflow;
            }
        }
    }

_last_literals:
    {   size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit == fillOutput) oend += LASTLITERALS;
        if (limit && (op + totalSize > oend)) {
            if (limit == limitedOutput) return 0;
            lastRunSize = (size_t)(oend - op) - 1;
            llAdd = (lastRunSize + 256 - RUN_MASK) / 256;
            lastRunSize -= llAdd;
        }
        ip = anchor + lastRunSize;

        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }

    *srcSizePtr = (int)(((const char *)ip) - source);
    return (int)((char *)op - dst);

_dest_overflow:
    return 0;
}

/* ------------------------------------------------------------------ */
/* level dispatch                                                      */
/* ------------------------------------------------------------------ */

typedef enum { strat_hc, strat_opt } hcstrat_e;
typedef struct { hcstrat_e strat; int nbSearches; unsigned targetLength; } cparams_t;

static const cparams_t k_clTable[LZ4HC_CLEVEL_MAX + 1] = {
    { strat_hc,      2,  16 },  /* 0, unused */
    { strat_hc,      2,  16 },  /* 1, unused */
    { strat_hc,      2,  16 },  /* 2 */
    { strat_hc,      4,  16 },  /* 3 */
    { strat_hc,      8,  16 },  /* 4 */
    { strat_hc,     16,  16 },  /* 5 */
    { strat_hc,     32,  16 },  /* 6 */
    { strat_hc,     64,  16 },  /* 7 */
    { strat_hc,    128,  16 },  /* 8 */
    { strat_hc,    256,  16 },  /* 9 */
    { strat_opt,    96,  64 },  /* 10 */
    { strat_opt,   512, 128 },  /* 11 */
    { strat_opt, 16384, LZ4_OPT_NUM }, /* 12 */
};

static int LZ4HC_compress_generic_internal(
        lz4hc_ctx_t *const ctx,
        const char *const src,
        char *const dst,
        int *const srcSizePtr,
        int const dstCapacity,
        int cLevel,
        const limit_e limit,
        const dictctx_e dict)
{
    if (limit == fillOutput && dstCapacity < 1) return 0;
    if ((unsigned)*srcSizePtr > (unsigned)LZ4_MAX_INPUT_SIZE) return 0;

    ctx->end += *srcSizePtr;
    if (cLevel < 1) cLevel = LZ4HC_CLEVEL_DEFAULT;
    cLevel = MIN_(LZ4HC_CLEVEL_MAX, cLevel);
    {   cparams_t const cParam = k_clTable[cLevel];
        hcfavor_e const favor = ctx->favorDecSpeed ? favorDecompressionSpeed : favorCompressionRatio;
        int result;

        if (cParam.strat == strat_hc) {
            result = LZ4HC_compress_hashChain(ctx, src, dst, srcSizePtr, dstCapacity,
                                              cParam.nbSearches, limit, dict);
        } else {
            result = LZ4HC_compress_optimal(ctx, src, dst, srcSizePtr, dstCapacity,
                                            cParam.nbSearches, cParam.targetLength, limit,
                                            cLevel == LZ4HC_CLEVEL_MAX, dict, favor);
        }
        if (result <= 0) ctx->dirty = 1;
        return result;
    }
}

static void LZ4HC_setExternalDict(lz4hc_ctx_t *ctxPtr, const BYTE *newBlock)
{
    if (ctxPtr->end >= ctxPtr->prefixStart + 4)
        LZ4HC_Insert(ctxPtr, ctxPtr->end - 3);

    ctxPtr->lowLimit = ctxPtr->dictLimit;
    ctxPtr->dictStart = ctxPtr->prefixStart;
    ctxPtr->dictLimit += (U32)(ctxPtr->end - ctxPtr->prefixStart);
    ctxPtr->prefixStart = newBlock;
    ctxPtr->end = newBlock;
    ctxPtr->nextToUpdate = ctxPtr->dictLimit;

    ctxPtr->dictCtx = NULL;
}

static int LZ4HC_compress_generic_noDictCtx(
        lz4hc_ctx_t *const ctx, const char *const src, char *const dst,
        int *const srcSizePtr, int const dstCapacity, int cLevel, limit_e limit)
{
    return LZ4HC_compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity,
                                           cLevel, limit, noDictCtx);
}

static int LZ4HC_compress_generic_dictCtx(
        lz4hc_ctx_t *const ctx, const char *const src, char *const dst,
        int *const srcSizePtr, int const dstCapacity, int cLevel, limit_e limit)
{
    const size_t position = (size_t)(ctx->end - ctx->prefixStart) + (ctx->dictLimit - ctx->lowLimit);
    if (position >= 64 * KB_) {
        ctx->dictCtx = NULL;
        return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    } else if (position == 0 && *srcSizePtr > 4 * KB_) {
        memcpy(ctx, ctx->dictCtx, sizeof(lz4hc_ctx_t));
        LZ4HC_setExternalDict(ctx, (const BYTE *)src);
        ctx->compressionLevel = (short)cLevel;
        return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    } else {
        return LZ4HC_compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity,
                                               cLevel, limit, usingDictCtxHc);
    }
}

static int LZ4HC_compress_generic(
        lz4hc_ctx_t *const ctx, const char *const src, char *const dst,
        int *const srcSizePtr, int const dstCapacity, int cLevel, limit_e limit)
{
    if (ctx->dictCtx == NULL)
        return LZ4HC_compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    return LZ4HC_compress_generic_dictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
}

/* ------------------------------------------------------------------ */
/* public API                                                          */
/* ------------------------------------------------------------------ */

void LZ4_setCompressionLevel(lz4hc_ctx_t *s, int level)
{
    if (level < 1) level = LZ4HC_CLEVEL_DEFAULT;
    if (level > LZ4HC_CLEVEL_MAX) level = LZ4HC_CLEVEL_MAX;
    s->compressionLevel = (short)level;
}

void LZ4_favorDecompressionSpeed(lz4hc_ctx_t *s, int favor)
{
    s->favorDecSpeed = (signed char)(favor != 0);
}

void LZ4_initStreamHC(lz4hc_ctx_t *s)
{
    memset(s, 0, sizeof(*s));
    LZ4_setCompressionLevel(s, LZ4HC_CLEVEL_DEFAULT);
}

void LZ4_resetStreamHC_fast(lz4hc_ctx_t *s, int level)
{
    if (s->dirty) {
        signed char const favor = s->favorDecSpeed;
        LZ4_initStreamHC(s);
        s->favorDecSpeed = favor;
    } else {
        s->dictLimit += (U32)(s->end - s->prefixStart);
        s->prefixStart = NULL;
        s->end = NULL;
        s->dictStart = NULL;
    }
    LZ4_setCompressionLevel(s, level);
}

int LZ4_compress_HC_extStateHC_fastReset(lz4hc_ctx_t *s, const char *src, char *dst,
                                         int srcSize, int dstCapacity, int level)
{
    LZ4_resetStreamHC_fast(s, level);
    LZ4HC_init_internal(s, (const BYTE *)src);
    if (dstCapacity < LZ4_compressBound(srcSize))
        return LZ4HC_compress_generic(s, src, dst, &srcSize, dstCapacity, level, limitedOutput);
    return LZ4HC_compress_generic(s, src, dst, &srcSize, dstCapacity, level, notLimited);
}

int LZ4_loadDictHC(lz4hc_ctx_t *s, const char *dictionary, int dictSize)
{
    const BYTE *p = (const BYTE *)dictionary;
    if (dictSize > 64 * KB_) {
        p += dictSize - 64 * KB_;
        dictSize = 64 * KB_;
    }
    /* need a full reset so that indexes remain valid */
    {   short const level = s->compressionLevel;
        signed char const favor = s->favorDecSpeed;
        LZ4_initStreamHC(s);
        s->compressionLevel = level;
        s->favorDecSpeed = favor;
    }
    LZ4HC_init_internal(s, p);
    s->end = p + dictSize;
    if (dictSize >= 4) LZ4HC_Insert(s, s->end - 3);
    return dictSize;
}

void LZ4_attach_HC_dictionary(lz4hc_ctx_t *working, const lz4hc_ctx_t *dictCtx)
{
    working->dictCtx = dictCtx;
}

static void LZ4HC_renormDictT(lz4hc_ctx_t *ctxPtr, int nextSize)
{
    if (ctxPtr->end - ctxPtr->prefixStart + nextSize > (ptrdiff_t)(2u << 30)) {
        size_t const dictSize = (size_t)(ctxPtr->end - ctxPtr->prefixStart);
        const BYTE *dictBegin = ctxPtr->prefixStart;
        int i;
        LZ4HC_clearTables(ctxPtr);
        ctxPtr->dictLimit = 0;
        ctxPtr->lowLimit = 0;
        ctxPtr->nextToUpdate = 0;
        ctxPtr->prefixStart = dictBegin;
        ctxPtr->end = dictBegin + dictSize;
        ctxPtr->dictStart = dictBegin;
        (void)i;
    }
}

int LZ4_compress_HC_continue(lz4hc_ctx_t *ctxPtr, const char *src, char *dst,
                             int srcSize, int dstCapacity)
{
    limit_e const limit = (dstCapacity < LZ4_compressBound(srcSize)) ? limitedOutput : notLimited;

    LZ4HC_renormDictT(ctxPtr, srcSize);
    if (ctxPtr->dirty) return 0;
    if (ctxPtr->prefixStart == NULL) LZ4HC_init_internal(ctxPtr, (const BYTE *)src);

    /* check overlapping input / dictionary space */
    {   const char *sourceEnd = src + srcSize;
        const char *const dictBegin = (const char *)ctxPtr->dictStart;
        const char *const dictEnd = (const char *)ctxPtr->dictStart + (ctxPtr->dictLimit - ctxPtr->lowLimit);
        if ((sourceEnd > dictBegin) && ((const char *)src < dictEnd)) {
            if (sourceEnd > dictEnd) sourceEnd = dictEnd;
            ctxPtr->lowLimit += (U32)(sourceEnd - ctxPtr->dictStart);
            ctxPtr->dictStart += (U32)(sourceEnd - (const char *)ctxPtr->dictStart);
            if (ctxPtr->dictLimit - ctxPtr->lowLimit < 4) {
                ctxPtr->lowLimit = ctxPtr->dictLimit;
                ctxPtr->dictStart = ctxPtr->prefixStart;
            }
        }
    }

    /* do the blocks follow each other? */
    if ((const BYTE *)src != ctxPtr->end)
        LZ4HC_setExternalDict(ctxPtr, (const BYTE *)src);

    return LZ4HC_compress_generic(ctxPtr, src, dst, &srcSize, dstCapacity,
                                  ctxPtr->compressionLevel, limit);
}

int LZ4_saveDictHC(lz4hc_ctx_t *ctxPtr, char *safeBuffer, int dictSize)
{
    int const prefixSize = (int)(ctxPtr->end - ctxPtr->prefixStart);
    if (dictSize > 64 * KB_) dictSize = 64 * KB_;
    if (dictSize < 4) dictSize = 0;
    if (dictSize > prefixSize) dictSize = prefixSize;
    if (safeBuffer == NULL) return dictSize;
    if (dictSize > 0)
        memmove(safeBuffer, ctxPtr->end - dictSize, (size_t)dictSize);
    {   U32 const endIndex = (U32)(ctxPtr->end - ctxPtr->prefixStart) + ctxPtr->dictLimit;
        ctxPtr->end = (const BYTE *)safeBuffer + dictSize;
        ctxPtr->prefixStart = ctxPtr->end - dictSize;
        ctxPtr->dictLimit = endIndex - (U32)dictSize;
        ctxPtr->lowLimit = endIndex - (U32)dictSize;
        ctxPtr->dictStart = ctxPtr->prefixStart;
        if (ctxPtr->nextToUpdate < ctxPtr->dictLimit)
            ctxPtr->nextToUpdate = ctxPtr->dictLimit;
    }
    return dictSize;
}

