#include <stdlib.h>
#include <string.h>
#include "lz4hc.h"
#include "lz4blk.h"
static lz4hc_ctx_t st;
int main(int argc, char**argv){
    const char* path = argv[1];
    int level = argc>2?atoi(argv[2]):9;
    int favor = argc>3?atoi(argv[3]):0;
    FILE*f=fopen(path,"rb"); if(!f){perror("open");return 1;}
    fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
    char* in = malloc(n?n:1); if(fread(in,1,n,f)!=(size_t)n){} fclose(f);
    char* out = malloc(n+1024);
    LZ4_initStreamHC(&st);
    LZ4_favorDecompressionSpeed(&st, favor);
    int r = LZ4_compress_HC_extStateHC_fastReset(&st, in, out, (int)n, (int)n-1, level);
    if (r<=0) { printf("UNCOMPRESSED\n"); return 0; }
    for (int i=0;i<r;i++) printf("%02x", (unsigned char)out[i]);
    printf("\n");
    return 0;
}
